# 3) Minimal parser/validator helper

This is the basic utility you’ll want on the server.

```ts
import { BrainDumpPlanSchema, type BrainDumpPlan } from "./schema";

export function parseBrainDumpPlan(raw: string): BrainDumpPlan {
  const parsed = JSON.parse(raw);
  return BrainDumpPlanSchema.parse(parsed);
}
```

That’s the simplest version.

---

# 4) Safer parser with success/error result

This version is better for production because it won’t throw unless you want it to.

```ts
import { BrainDumpPlanSchema, type BrainDumpPlan } from "./schema";

export type ParseResult =
  | { success: true; data: BrainDumpPlan }
  | { success: false; error: string; raw: string };

export function safeParseBrainDumpPlan(raw: string): ParseResult {
  try {
    const parsed = JSON.parse(raw);
    const validated = BrainDumpPlanSchema.safeParse(parsed);

    if (!validated.success) {
      return {
        success: false,
        error: validated.error.message,
        raw,
      };
    }

    return {
      success: true,
      data: validated.data,
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown parse error",
      raw,
    };
  }
}
```

