# 5) Optional normalization layer

Very useful in practice.

Sometimes models return:
- `null`
- missing arrays
- numbers instead of strings
- single strings where arrays are expected

You can keep the schema strict and add a normalizer before validation.

```ts
function asStringArray(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((item) => String(item));
  }
  if (typeof value === "string" && value.trim()) {
    return [value];
  }
  return [];
}

function asPriorityArray(value: unknown): { title: string; reason: string }[] {
  if (!Array.isArray(value)) return [];
  return value.map((item) => {
    const obj = item as Record<string, unknown>;
    return {
      title: String(obj?.title ?? ""),
      reason: String(obj?.reason ?? ""),
    };
  });
}

function asCommunicationDraftArray(
  value: unknown
): { recipient: string; draft: string }[] {
  if (!Array.isArray(value)) return [];
  return value.map((item) => {
    const obj = item as Record<string, unknown>;
    return {
      recipient: String(obj?.recipient ?? ""),
      draft: String(obj?.draft ?? ""),
    };
  });
}

export function normalizeBrainDumpPlan(input: unknown) {
  const obj = (input ?? {}) as Record<string, unknown>;
  const time = (obj.time_horizon ?? {}) as Record<string, unknown>;

  return {
    summary: String(obj.summary ?? ""),
    top_priorities: asPriorityArray(obj.top_priorities),
    next_actions: asStringArray(obj.next_actions),
    time_horizon: {
      today: asStringArray(time.today),
      this_week: asStringArray(time.this_week),
      later: asStringArray(time.later),
    },
    open_questions: asStringArray(obj.open_questions),
    blockers: asStringArray(obj.blockers),
    communication_drafts: asCommunicationDraftArray(obj.communication_drafts),
  };
}
```

Then use it like this:

```ts
import { BrainDumpPlanSchema } from "./schema";
import { normalizeBrainDumpPlan } from "./normalize";

export function parseWithNormalization(raw: string) {
  const parsed = JSON.parse(raw);
  const normalized = normalizeBrainDumpPlan(parsed);
  return BrainDumpPlanSchema.parse(normalized);
}
```

