# 9) Example OpenAI/LLM integration pattern

Generic server-side pattern:

```ts
import { safeParseBrainDumpPlan } from "./parse";
import { SYSTEM_PROMPT, buildUserPrompt } from "./prompts";

export async function generateBrainDumpPlan(brainDump: string) {
  const responseText = await callYourModel({
    system: SYSTEM_PROMPT,
    user: buildUserPrompt({ brainDump }),
  });

  const result = safeParseBrainDumpPlan(responseText);

  if (!result.success) {
    // log raw output for debugging
    console.error("Plan parse failed:", result.error);
    console.error("Raw model output:", result.raw);

    throw new Error("Failed to parse model response");
  }

  return result.data;
}
```

You’d replace `callYourModel` with your SDK call.

