# 6) `src/lib/planning/service.ts`

This includes:
- mock mode
- placeholder model call
- parsing
- normalization fallback

```ts
import { safeParseBrainDumpPlan } from "./parse";
import { normalizeBrainDumpPlan } from "./normalize";
import { BrainDumpPlanSchema, type BrainDumpPlan } from "./schema";
import { SYSTEM_PROMPT, buildUserPrompt } from "./prompts";
import { mockBrainDumpPlan } from "./mock";

type GenerateOptions = {
  brainDump: string;
  mode?: "work" | "personal" | "mixed";
  style?: "gentle" | "direct" | "executive";
  depth?: "quick" | "standard" | "detailed";
};

async function callYourModel(_args: {
  system: string;
  user: string;
}): Promise<string> {
  throw new Error("Model integration not implemented yet");
}

export async function generateBrainDumpPlan(
  options: GenerateOptions
): Promise<BrainDumpPlan> {
  const useMock = process.env.USE_MOCK_PLAN === "true";

  if (useMock) {
    return mockBrainDumpPlan;
  }

  const responseText = await callYourModel({
    system: SYSTEM_PROMPT,
    user: buildUserPrompt(options),
  });

  const result = safeParseBrainDumpPlan(responseText);

  if (result.success) {
    return result.data;
  }

  // fallback attempt: normalize then validate
  try {
    const parsed = JSON.parse(responseText);
    const normalized = normalizeBrainDumpPlan(parsed);
    return BrainDumpPlanSchema.parse(normalized);
  } catch (error) {
    console.error("Plan parse failed:", result.error);
    console.error("Raw model output:", result.raw);
    throw new Error(
      error instanceof Error ? error.message : "Failed to parse plan response"
    );
  }
}
```

