import { NextRequest, NextResponse } from "next/server";
import { generateBrainDumpPlan } from "@/lib/planning/service";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();

    const brainDump = String(body.brainDump ?? "").trim();
    const mode = body.mode;
    const style = body.style;
    const depth = body.depth;

    if (!brainDump) {
      return NextResponse.json(
        { error: "brainDump is required" },
        { status: 400 }
      );
    }

    const plan = await generateBrainDumpPlan({
      brainDump,
      mode,
      style,
      depth,
    });

    return NextResponse.json({ plan });
  } catch (error) {
    console.error("POST /api/plan failed", error);
    return NextResponse.json(
      { error: "Failed to generate plan" },
      { status: 500 }
    );
  }
}
```

