"use client";

import { useState } from "react";
import type { BrainDumpPlan } from "@/lib/planning/schema";

type Props = {
  onResult: (plan: BrainDumpPlan) => void;
};

export function BrainDumpForm({ onResult }: Props) {
  const [brainDump, setBrainDump] = useState("");
  const [mode, setMode] = useState<"work" | "personal" | "mixed">("mixed");
  const [style, setStyle] = useState<"gentle" | "direct" | "executive">("direct");
  const [depth, setDepth] = useState<"quick" | "standard" | "detailed">("standard");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      const res = await fetch("/api/plan", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          brainDump,
          mode,
          style,
          depth,
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data?.error || "Something went wrong");
      }

      onResult(data.plan);
