# 3) Schema-enforced `service.ts`

Replace `src/lib/planning/service.ts` with this:

```ts
import OpenAI from "openai";
import { z } from "zod";
import { BrainDumpPlanSchema, type BrainDumpPlan } from "./schema";
import { normalizeBrainDumpPlan } from "./normalize";
import { SYSTEM_PROMPT, buildUserPrompt } from "./prompts";
import { mockBrainDumpPlan } from "./mock";
import { brainDumpPlanJsonSchema } from "./jsonSchema";

type GenerateOptions = {
  brainDump: string;
  mode?: "work" | "personal" | "mixed";
  style?: "gentle" | "direct" | "executive";
  depth?: "quick" | "standard" | "detailed";
};

const client = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
});

function extractStructuredJson(outputText: string): unknown {
  try {
    return JSON.parse(outputText);
  } catch {
    return null;
  }
}

async function callStructuredModel(args: {
  system: string;
  user: string;
}): Promise<unknown> {
  const model = process.env.OPENAI_MODEL || "gpt-4.1-mini";

  const response = await client.responses.create({
    model,
    input: [
      {
        role: "system",
        content: args.system,
      },
      {
        role: "user",
        content: args.user,
      },
    ],
    text: {
      format: {
        type: "json_schema",
        name: brainDumpPlanJsonSchema.name,
        schema: brainDumpPlanJsonSchema.schema,
        strict: true,
      },
    },
  });

  // Best case: the SDK gives structured JSON text directly
  if (response.output_text && response.output_text.trim()) {
    const parsed = extractStructuredJson(response.output_text);
    if (parsed !== null) return parsed;
  }

  // Fallback for unexpected SDK response shapes during debugging
  return null;
}

export async function generateBrainDumpPlan(
  options: GenerateOptions
): Promise<BrainDumpPlan> {
  const useMock = process.env.USE_MOCK_PLAN === "true";

  if (useMock) {
    return mockBrainDumpPlan;
  }

  if (!process.env.OPENAI_API_KEY) {
    throw new Error("Missing OPENAI_API_KEY");
  }

  const structured = await callStructuredModel({
    system: SYSTEM_PROMPT,
    user: buildUserPrompt(options),
  });

  if (!structured) {
    throw new Error("Model did not return valid structured output");
  }

  // First try strict validation
  const validated = BrainDumpPlanSchema.safeParse(structured);
  if (validated.success) {
    return validated.data;
  }

  // Then try normalization + validation as a backup
  try {
    const normalized = normalizeBrainDumpPlan(structured);
    return BrainDumpPlanSchema.parse(normalized);
  } catch (error) {
    console.error("Structured output validation failed");
    console.error(
      "Validation error:",
      validated.error instanceof z.ZodError
        ? validated.error.flatten()
        : validated.error
    );
    console.error("Raw structured output:", JSON.stringify(structured, null, 2));

    throw new Error(
      error instanceof Error
        ? error.message
        : "Failed to validate structured plan response"
    );
  }
}
```

