# 1) Update `src/lib/planning/service.ts`

Here’s a version that keeps your current behavior but adds a debug path.

```ts
import OpenAI from "openai";
import { z } from "zod";
import { BrainDumpPlanSchema, type BrainDumpPlan } from "./schema";
import { normalizeBrainDumpPlan } from "./normalize";
import { SYSTEM_PROMPT, buildUserPrompt } from "./prompts";
import { mockBrainDumpPlan } from "./mock";
import { brainDumpPlanJsonSchema } from "./jsonSchema";

type GenerateOptions = {
  brainDump: string;
  mode?: "work" | "personal" | "mixed";
  style?: "gentle" | "direct" | "executive";
  depth?: "quick" | "standard" | "detailed";
};

export type StructuredModelCallResult = {
  rawResponse: unknown;
  outputText: string;
  parsedStructured: unknown | null;
  model: string;
};

export type GeneratePlanDebugResult = {
  plan: BrainDumpPlan;
  debug: {
    usedMock: boolean;
    model: string;
    promptVersion?: string;
    strictValidationPassed: boolean;
    normalizationUsed: boolean;
    rawResponse: unknown;
    outputText: string;
    parsedStructured: unknown | null;
  };
};

const client = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
});

function tryParseJson(text: string): unknown | null {
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

async function callStructuredModel(args: {
  system: string;
  user: string;
}): Promise<StructuredModelCallResult> {
  const model = process.env.OPENAI_MODEL || "gpt-4.1-mini";

  const response = await client.responses.create({
    model,
    input: [
      {
        role: "system",
        content: args.system,
      },
      {
        role: "user",
        content: args.user,
      },
    ],
    text: {
      format: {
        type: "json_schema",
        name: brainDumpPlanJsonSchema.name,
        schema: brainDumpPlanJsonSchema.schema,
        strict: true,
      },
    },
  });

  const outputText = response.output_text ?? "";
  const parsedStructured = outputText.trim() ? tryParseJson(outputText) : null;

  return {
    rawResponse: response,
    outputText,
    parsedStructured,
    model,
  };
}

export async function generateBrainDumpPlanDebug(
  options: GenerateOptions
): Promise<GeneratePlanDebugResult> {
  const useMock = process.env.USE_MOCK_PLAN === "true";
  const model = process.env.OPENAI_MODEL || "gpt-4.1-mini";

  if (useMock) {
    return {
      plan: mockBrainDumpPlan,
      debug: {
        usedMock: true,
        model,
        strictValidationPassed: true,
        normalizationUsed: false,
        rawResponse: { mock: true },
        outputText: JSON.stringify(mockBrainDumpPlan, null, 2),
        parsedStructured: mockBrainDumpPlan,
      },
    };
  }

  if (!process.env.OPENAI_API_KEY) {
    throw new Error("Missing OPENAI_API_KEY");
  }

  const structuredResult = await callStructuredModel({
    system: SYSTEM_PROMPT,
    user: buildUserPrompt(options),
  });

  if (!structuredResult.parsedStructured) {
    console.error("Model did not return parseable structured output");
    console.error("Output text:", structuredResult.outputText);
    throw new Error("Model did not return valid structured output");
  }

  const strictValidated = BrainDumpPlanSchema.safeParse(
    structuredResult.parsedStructured
  );

  if (strictValidated.success) {
    return {
      plan: strictValidated.data,
      debug: {
        usedMock: false,
        model: structuredResult.model,
        strictValidationPassed: true,
        normalizationUsed: false,
        rawResponse: structuredResult.rawResponse,
        outputText: structuredResult.outputText,
        parsedStructured: structuredResult.parsedStructured,
      },
    };
  }

  try {
    const normalized = normalizeBrainDumpPlan(structuredResult.parsedStructured);
    const parsed = BrainDumpPlanSchema.parse(normalized);

    return {
      plan: parsed,
      debug: {
        usedMock: false,
        model: structuredResult.model,
        strictValidationPassed: false,
        normalizationUsed: true,
        rawResponse: structuredResult.rawResponse,
        outputText: structuredResult.outputText,
        parsedStructured: structuredResult.parsedStructured,
      },
    };
  } catch (error) {
    console.error("Structured output validation failed");
    console.error(
      "Validation error:",
      strictValidated.error instanceof z.ZodError
        ? strictValidated.error.flatten()
        : strictValidated.error
    );
    console.error(
      "Parsed structured output:",
      JSON.stringify(structuredResult.parsedStructured, null, 2)
    );

    throw new Error(
      error instanceof Error
        ? error.message
        : "Failed to validate structured plan response"
    );
  }
}

export async function generateBrainDumpPlan(
  options: GenerateOptions
): Promise<BrainDumpPlan> {
  const result = await generateBrainDumpPlanDebug(options);
  return result.plan;
}
```

