# 4) Update `src/eval/runEval.ts`

Switch the eval runner to use the debug function.

```ts
import path from "node:path";
import { evalCases } from "./cases";
import type { EvalResult } from "./types";
import { writeJsonFile, writeTextFile, timestamp, ensureDir } from "./utils";
import { generateBrainDumpPlanDebug } from "../lib/planning/service";
import { PROMPT_VERSION } from "../lib/planning/prompts";

const MODEL = process.env.OPENAI_MODEL || "gpt-4.1-mini";
const OUTPUT_DIR = path.join(process.cwd(), "eval-results", timestamp());

async function run() {
  console.log(`Running eval suite with model=${MODEL}, prompt=${PROMPT_VERSION}`);
  await ensureDir(OUTPUT_DIR);

  const summary: EvalResult[] = [];

  for (const testCase of evalCases) {
    console.log(`\n→ ${testCase.id}: ${testCase.name}`);

    const started = Date.now();

    try {
      const resultDebug = await generateBrainDumpPlanDebug({
        brainDump: testCase.brainDump,
        mode: "mixed",
        style: "direct",
        depth: "standard",
      });

      const durationMs = Date.now() - started;

      const result: EvalResult = {
        caseId: testCase.id,
        caseName: testCase.name,
        category: testCase.category,
        brainDump: testCase.brainDump,
        success: true,
        durationMs,
        output: resultDebug.plan,
        debug: {
          ...resultDebug.debug,
          promptVersion: PROMPT_VERSION,
        },
        createdAt: new Date().toISOString(),
        model: MODEL,
        promptVersion: PROMPT_VERSION,
      };

      summary.push(result);

      await writeJsonFile(path.join(OUTPUT_DIR, `${testCase.id}.json`), result);

      console.log(
        `  success (${durationMs}ms) strict=${resultDebug.debug.strictValidationPassed} normalized=${resultDebug.debug.normalizationUsed}`
      );
    } catch (error) {
      const durationMs = Date.now() - started;

      const result: EvalResult = {
        caseId: testCase.id,
        caseName: testCase.name,
        category: testCase.category,
        brainDump: testCase.brainDump,
        success: false,
        durationMs,
        error: error instanceof Error ? error.message : "Unknown error",
        createdAt: new Date().toISOString(),
        model: MODEL,
        promptVersion: PROMPT_VERSION,
      };

      summary.push(result);

      await writeJsonFile(path.join(OUTPUT_DIR, `${testCase.id}.json`), result);

      console.log(`  failed (${durationMs}ms): ${result.error}`);
    }
  }

  await writeJsonFile(path.join(OUTPUT_DIR, "summary.json"), summary);

  const md = buildMarkdownSummary(summary);
  await writeTextFile(path.join(OUTPUT_DIR, "summary.md"), md);

  const csv = buildScoringCsv(summary);
  await writeTextFile(path.join(OUTPUT_DIR, "scoring.csv"), csv);

  console.log(`\nDone. Results written to:\n${OUTPUT_DIR}`);
}

function buildMarkdownSummary(results: EvalResult[]) {
  const total = results.length;
  const successCount = results.filter((r) => r.success).length;
  const failureCount = total - successCount;
  const avgDuration =
    results.reduce((sum, r) => sum + r.durationMs, 0) / Math.max(total, 1);

  const strictPasses = results.filter(
    (r) => r.success && r.debug?.strictValidationPassed
  ).length;

  const normalizedCount = results.filter(
    (r) => r.success && r.debug?.normalizationUsed
  ).length;

  const lines: string[] = [];

  lines.push(`# Eval Summary`);
  lines.push("");
  lines.push(`- Model: ${MODEL}`);
  lines.push(`- Prompt version: ${PROMPT_VERSION}`);
  lines.push(`- Total cases: ${total}`);
  lines.push(`- Successes: ${successCount}`);
  lines.push(`- Failures: ${failureCount}`);
  lines.push(`- Strict validation passes: ${strictPasses}`);
  lines.push(`- Normalization fallback used: ${normalizedCount}`);
  lines.push(`- Avg duration: ${Math.round(avgDuration)}ms`);
  lines.push("");

  lines.push(`## Case Results`);
  lines.push("");
  lines.push(`| Case | Category | Success | Strict | Normalized | Duration | Error |`);
  lines.push(`|---|---|---:|---:|---:|---:|---|`);

  for (const r of results) {
    lines.push(
      `| ${r.caseId} - ${r.caseName} | ${r.category} | ${r.success ? "yes" : "no"} | ${r.debug?.strictValidationPassed ? "yes" : ""} | ${r.debug?.normalizationUsed ? "yes" : ""} | ${r.durationMs}ms | ${r.error ?? ""} |`
    );
  }

  return lines.join("\n");
}

function buildScoringCsv(results: EvalResult[]) {
  const headers = [
    "caseId",
    "caseName",
    "category",
    "model",
    "promptVersion",
    "success",
    "strictValidationPassed",
    "normalizationUsed",
    "priorityQuality",
    "nextActionQuality",
    "timeHorizonUsefulness",
    "decisionDetection",
    "blockerDetection",
    "draftUsefulness",
    "overwhelmReduction",
    "schemaReliability",
    "goldenAlignment",
    "notes",
  ];

  const rows = results.map((r) =>
    [
      r.caseId,
      `"${r.caseName}"`,
      r.category,
      r.model,
      r.promptVersion,
      r.success ? "true" : "false",
      r.debug?.strictValidationPassed ? "true" : "false",
      r.debug?.normalizationUsed ? "true" : "false",
      "",
      "",
      "",
      "",
      "",
      "",
      "",
      "",
      "",
      '""',
    ].join(",")
  );

  return [headers.join(","), ...rows].join("\n");
}

run().catch((error) => {
  console.error("Eval runner crashed:", error);
  process.exit(1);
});
```

