# 4) Build the side-by-side comparison runner

## `src/eval/comparePrompts.ts`

```ts
import path from "node:path";
import { evalCases } from "./cases";
import { ensureDir, timestamp, writeJsonFile, writeTextFile } from "./utils";
import { generateBrainDumpPlanDebug } from "../lib/planning/service";
import {
  PROMPT_V1,
  PROMPT_V2,
  type PromptConfig,
} from "../lib/planning/prompts";
import type {
  PromptComparisonCaseResult,
  PromptComparisonSummary,
} from "./compareTypes";

const MODEL = process.env.OPENAI_MODEL || "gpt-4.1-mini";
const OUTPUT_DIR = path.join(
  process.cwd(),
  "eval-comparisons",
  timestamp()
);

const PROMPTS_TO_COMPARE: PromptConfig[] = [PROMPT_V1, PROMPT_V2];

async function run() {
  console.log(
    `Comparing prompts [${PROMPTS_TO_COMPARE.map((p) => p.version).join(", ")}] with model=${MODEL}`
  );

  await ensureDir(OUTPUT_DIR);

  const caseSummaries: PromptComparisonCaseResult[] = [];

  for (const testCase of evalCases) {
    console.log(`\n→ ${testCase.id}: ${testCase.name}`);

    const caseResult: PromptComparisonCaseResult = {
      caseId: testCase.id,
      caseName: testCase.name,
      category: testCase.category,
      brainDump: testCase.brainDump,
      results: [],
    };

    for (const promptConfig of PROMPTS_TO_COMPARE) {
      const started = Date.now();

      try {
        const resultDebug = await generateBrainDumpPlanDebug({
          brainDump: testCase.brainDump,
          mode: "mixed",
          style: "direct",
          depth: "standard",
          promptConfig,
        });

        const durationMs = Date.now() - started;

        caseResult.results.push({
          promptVersion: promptConfig.version,
          success: true,
          durationMs,
          output: resultDebug.plan,
          debug: {
            strictValidationPassed: resultDebug.debug.strictValidationPassed,
            normalizationUsed: resultDebug.debug.normalizationUsed,
            outputText: resultDebug.debug.outputText,
            parsedStructured: resultDebug.debug.parsedStructured,
            systemPrompt: resultDebug.debug.systemPrompt,
            userPrompt: resultDebug.debug.userPrompt,
          },
        });

        console.log(
          `  ${promptConfig.version}: success (${durationMs}ms) strict=${resultDebug.debug.strictValidationPassed} normalized=${resultDebug.debug.normalizationUsed}`
        );
      } catch (error) {
        const durationMs = Date.now() - started;

        caseResult.results.push({
          promptVersion: promptConfig.version,
          success: false,
          durationMs,
          error: error instanceof Error ? error.message : "Unknown error",
        });

        console.log(
          `  ${promptConfig.version}: failed (${durationMs}ms)`
        );
      }
    }

    caseSummaries.push(caseResult);

    await writeJsonFile(
      path.join(OUTPUT_DIR, `${testCase.id}.comparison.json`),
      caseResult
    );
  }

  const summary: PromptComparisonSummary = {
    model: MODEL,
    comparedPromptVersions: PROMPTS_TO_COMPARE.map((p) => p.version),
    createdAt: new Date().toISOString(),
    totalCases: evalCases.length,
    cases: caseSummaries,
  };

  await writeJsonFile(path.join(OUTPUT_DIR, "comparison-summary.json"), summary);
  await writeTextFile(
    path.join(OUTPUT_DIR, "comparison-summary.md"),
    buildMarkdownComparison(summary)
  );
  await writeTextFile(
    path.join(OUTPUT_DIR, "comparison-scoring.csv"),
    buildComparisonScoringCsv(summary)
  );

  console.log(`\nDone. Comparison written to:\n${OUTPUT_DIR}`);
}

function buildMarkdownComparison(summary: PromptComparisonSummary) {
  const lines: string[] = [];

  lines.push(`# Prompt Comparison Summary`);
  lines.push("");
  lines.push(`- Model: ${summary.model}`);
  lines.push(`- Prompt versions: ${summary.comparedPromptVersions.join(", ")}`);
  lines.push(`- Total cases: ${summary.totalCases}`);
  lines.push(`- Created at: ${summary.createdAt}`);
  lines.push("");

  lines.push(`## Case Overview`);
  lines.push("");
  lines.push(`| Case | Category | Prompt | Success | Strict | Normalized | Duration | Error |`);
  lines.push(`|---|---|---|---:|---:|---:|---:|---|`);

  for (const c of summary.cases) {
    for (const r of c.results) {
      lines.push(
        `| ${c.caseId} - ${c.caseName} | ${c.category} | ${r.promptVersion} | ${r.success ? "yes" : "no"} | ${r.debug?.strictValidationPassed ? "yes" : ""} | ${r.debug?.normalizationUsed ? "yes" : ""} | ${r.durationMs}ms | ${r.error ?? ""} |`
      );
    }
  }

  return lines.join("\n");
}

function buildComparisonScoringCsv(summary: PromptComparisonSummary) {
  const headers = [
    "caseId",
    "caseName",
    "category",
    "model",
    "promptVersion",
    "success",
    "strictValidationPassed",
    "normalizationUsed",
    "priorityQuality",
    "nextActionQuality",
    "timeHorizonUsefulness",
    "decisionDetection",
    "blockerDetection",
    "draftUsefulness",
    "overwhelmReduction",
    "schemaReliability",
    "goldenAlignment",
    "notes",
  ];

  const rows: string[] = [];

  for (const c of summary.cases) {
    for (const r of c.results) {
      rows.push(
        [
          c.caseId,
          `"${c.caseName}"`,
          c.category,
          summary.model,
          r.promptVersion,
          r.success ? "true" : "false",
          r.debug?.strictValidationPassed ? "true" : "false",
          r.debug?.normalizationUsed ? "true" : "false",
          "",
          "",
          "",
          "",
          "",
          "",
          "",
          "",
          "",
          '""',
        ].join(",")
      );
    }
  }

  return [headers.join(","), ...rows].join("\n");
}

run().catch((error) => {
  console.error("Prompt comparison runner crashed:", error);
  process.exit(1);
});
```

