function buildMarkdownComparison(summary: PromptComparisonSummary) {
  const lines: string[] = [];

  lines.push(`# Prompt Comparison Summary`);
  lines.push("");
  lines.push(`- Model: ${summary.model}`);
  lines.push(`- Prompt versions: ${summary.comparedPromptVersions.join(", ")}`);
  lines.push(`- Total cases: ${summary.totalCases}`);
  lines.push(`- Created at: ${summary.createdAt}`);
  lines.push("");

  lines.push(`## Case Overview`);
  lines.push("");
  lines.push(
    `| Case | Category | Prompt | Success | Strict | Normalized | Heuristic Score | Duration | Error |`
  );
  lines.push(`|---|---|---|---:|---:|---:|---:|---:|---|`);

  for (const c of summary.cases) {
    for (const r of c.results) {
      lines.push(
        `| ${c.caseId} - ${c.caseName} | ${c.category} | ${r.promptVersion} | ${r.success ? "yes" : "no"} | ${r.debug?.strictValidationPassed ? "yes" : ""} | ${r.debug?.normalizationUsed ? "yes" : ""} | ${r.heuristics?.score ?? ""} | ${r.durationMs}ms | ${r.error ?? ""} |`
      );
    }
  }

  lines.push("");
  lines.push(`## Heuristic Warnings`);
  lines.push("");

  for (const c of summary.cases) {
    lines.push(`### ${c.caseId} - ${c.caseName}`);
    lines.push("");

    for (const r of c.results) {
      lines.push(`- **${r.promptVersion}**`);
      if (!r.success) {
        lines.push(`  - Failed: ${r.error ?? "Unknown error"}`);
        continue;
      }

      if (!r.heuristics || r.heuristics.warnings.length === 0) {
        lines.push(`  - No heuristic warnings`);
        continue;
      }

      for (const warning of r.heuristics.warnings) {
        lines.push(`  - ${warning}`);
      }
    }

    lines.push("");
  }

  return lines.join("\n");
}
