import type { BrainDumpPlan } from "../lib/planning/schema";
import type { EvalCase } from "./types";
import type { HeuristicCheck } from "./heuristicTypes";

function lower(text: string) {
  return text.toLowerCase();
}

function includesAny(text: string, phrases: string[]) {
  const t = lower(text);
  return phrases.some((p) => t.includes(lower(p)));
}

function planText(plan: BrainDumpPlan) {
  return lower(
    [
      plan.summary,
      ...plan.top_priorities.map((p) => `${p.title} ${p.reason}`),
      ...plan.next_actions,
      ...plan.time_horizon.today,
      ...plan.time_horizon.this_week,
      ...plan.time_horizon.later,
      ...plan.open_questions,
      ...plan.blockers,
      ...plan.communication_drafts.map((d) => `${d.recipient} ${d.draft}`),
    ].join("\n")
  );
}

function priorityText(plan: BrainDumpPlan) {
  return lower(
    plan.top_priorities
      .map((p) => `${p.title} ${p.reason}`)
      .join("\n")
  );
}

function openQuestionText(plan: BrainDumpPlan) {
  return lower(plan.open_questions.join("\n"));
}

function blockerText(plan: BrainDumpPlan) {
  return lower(plan.blockers.join("\n"));
}

function draftText(plan: BrainDumpPlan) {
  return lower(
    plan.communication_drafts
      .map((d) => `${d.recipient} ${d.draft}`)
      .join("\n")
  );
}

function todayText(plan: BrainDumpPlan) {
  return lower(plan.time_horizon.today.join("\n"));
}

function nextActionsText(plan: BrainDumpPlan) {
  return lower(plan.next_actions.join("\n"));
}

function check(params: {
  id: string;
  passed: boolean;
  severity: "info" | "warning" | "error";
  message: string;
}): HeuristicCheck {
  return {
    ...params,
    scope: "case_specific",
  };
}

