import type { BrainDumpPlan } from "../lib/planning/schema";
import type { EvalCase } from "./types";
import type { HeuristicCheck, HeuristicEvaluation } from "./heuristicTypes";
import { evaluateCaseSpecificHeuristics } from "./caseSpecificHeuristics";

function normalizeText(text: string) {
  return text.toLowerCase().trim();
}

function containsAny(text: string, phrases: string[]) {
  const lower = normalizeText(text);
  return phrases.some((p) => lower.includes(p.toLowerCase()));
}

function countGenericActions(actions: string[]) {
  const genericStarts = [
    "work on",
    "handle",
    "deal with",
    "make progress on",
    "figure out",
    "continue",
    "review",
    "address",
    "fix things",
  ];

  return actions.filter((a) =>
    genericStarts.some((start) => normalizeText(a).startsWith(start))
  ).length;
}

function hasDependencySignals(input: string) {
  const signals = [
    "waiting on",
    "need feedback from",
    "still hasn’t",
    "still hasn't",
    "owes",
    "depends on",
    "legal",
    "finance",
    "send revised",
    "follow up",
    "ask",
    "send",
    "someone needs to confirm",
  ];

  return containsAny(input, signals);
}

function hasDecisionSignals(input: string) {
  const signals = [
    "not sure whether",
    "maybe",
    "should i",
    "should we",
    "whether to",
    "decide",
    "might",
    "push the webinar",
    "cut scope",
    "stay with friends or get a hotel",
    "drop one club",
    "enterprise pilot or focus on self-serve",
  ];

  return containsAny(input, signals);
}

function hasExplicitDeadlineSignals(input: string) {
  const signals = [
    "today",
    "tomorrow",
    "this week",
    "next friday",
    "monday",
    "thursday",
    "due",
    "late",
    "overdue",
  ];

  return containsAny(input, signals);
}

function looksOverwhelmed(input: string) {
  const signals = [
    "everything feels behind",
    "i don't even know where to start",
    "i don’t even know where to start",
    "too much",
    "overloaded",
    "behind",
    "doing nothing",
    "apartment is a disaster",
    "inbox is a mess",
  ];

  return containsAny(input, signals);
}

function countTotalTimeHorizonItems(plan: BrainDumpPlan) {
  return (
    plan.time_horizon.today.length +
    plan.time_horizon.this_week.length +
    plan.time_horizon.later.length
  );
}

function hasLikelyCommunicationNeed(input: string) {
  const signals = [
    "email",
    "message",
    "follow up",
    "follow-up",
    "ask",
    "respond",
    "reply",
    "send",
    "ping",
    "investor update",
    "candidate",
    "landlord",
    "manager",
    "sam",
    "finance",
    "legal",
    "jordan",
    "priya",
    "support",
    "dev",
    "alex",
  ];

  return containsAny(input, signals);
}

function hasEmptyOrThinSummary(plan: BrainDumpPlan) {
  return plan.summary.trim().length < 30;
}

function generalCheck(params: {
  id: string;
  passed: boolean;
  severity: "info" | "warning" | "error";
  message: string;
}): HeuristicCheck {
  return {
    ...params,
    scope: "general",
  };
}

export function evaluateHeuristics(
  testCase: EvalCase,
  plan: BrainDumpPlan
): HeuristicEvaluation {
  const checks: HeuristicCheck[] = [];

  const input = testCase.brainDump;
  const genericActionCount = countGenericActions(plan.next_actions);
  const dependencyHeavy = hasDependencySignals(input);
  const decisionHeavy = hasDecisionSignals(input);
  const hasDeadlines = hasExplicitDeadlineSignals(input);
  const overwhelmed = looksOverwhelmed(input);
  const communicationLikely = hasLikelyCommunicationNeed(input);

  checks.push(
    generalCheck({
      id: "summary_present",
      passed: !hasEmptyOrThinSummary(plan),
      severity: "error",
      message: "Summary should be present and meaningful.",
    })
  );

  checks.push(
    generalCheck({
      id: "has_priorities",
      passed: plan.top_priorities.length > 0,
      severity: "error",
      message: "Top priorities should not be empty.",
    })
  );

  checks.push(
    generalCheck({
      id: "has_next_actions",
      passed: plan.next_actions.length > 0,
      severity: "error",
      message: "Next actions should not be empty.",
    })
  );

  checks.push(
    generalCheck({
      id: "today_not_overloaded",
      passed: plan.time_horizon.today.length <= 5,
      severity: "warning",
      message: `Today has ${plan.time_horizon.today.length} items; keep it realistic.`,
    })
  );

  if (overwhelmed) {
    checks.push(
      generalCheck({
        id: "overwhelm_limited_next_actions",
        passed: plan.next_actions.length <= 3,
        severity: "warning",
        message: "Overwhelm-heavy inputs should usually have 3 or fewer next actions.",
      })
    );

    checks.push(
      generalCheck({
        id: "overwhelm_limited_today",
        passed: plan.time_horizon.today.length <= 4,
        severity: "warning",
        message: "Overwhelm-heavy inputs should keep today especially short.",
      })
    );
  }

  checks.push(
    generalCheck({
      id: "next_actions_not_too_generic",
      passed: genericActionCount <= 1,
      severity: "warning",
      message: `Detected ${genericActionCount} overly generic next actions.`,
    })
  );

  if (dependencyHeavy) {
    checks.push(
      generalCheck({
        id: "dependency_input_has_blockers",
        passed: plan.blockers.length > 0,
        severity: "warning",
        message: "Dependency-heavy input should usually produce at least one blocker.",
      })
    );
  }

  if (decisionHeavy) {
    checks.push(
      generalCheck({
        id: "decision_input_has_open_questions",
        passed: plan.open_questions.length > 0,
        severity: "warning",
        message: "Decision-heavy input should usually produce open questions.",
      })
    );
  }

  if (hasDeadlines) {
    checks.push(
      generalCheck({
        id: "deadline_input_has_near_term_plan",
        passed:
          plan.time_horizon.today.length > 0 || plan.time_horizon.this_week.length > 0,
        severity: "warning",
        message: "Deadline-sensitive input should produce a near-term plan.",
      })
    );
  }

  if (communicationLikely && dependencyHeavy) {
    checks.push(
      generalCheck({
        id: "dependency_input_has_draft_or_blocker",
        passed:
          plan.communication_drafts.length > 0 || plan.blockers.length > 0,
        severity: "warning",
        message:
          "Dependency-heavy communication input should usually produce a draft or blocker.",
      })
    );
  }

  if (testCase.category === "sparse_ambiguity") {
    checks.push(
      generalCheck({
        id: "sparse_input_not_overdrafted",
        passed: plan.communication_drafts.length <= 1,
        severity: "warning",
        message: "Sparse ambiguous input should not produce lots of forced drafts.",
      })
    );
  }

  checks.push(
    generalCheck({
      id: "nontrivial_total_output",
      passed: countTotalTimeHorizonItems(plan) + plan.top_priorities.length >= 4,
      severity: "warning",
      message: "Output may be too thin to be useful.",
    })
  );

  // Add case-specific checks
  checks.push(...evaluateCaseSpecificHeuristics(testCase, plan));

  const warnings = checks
    .filter((c) => !c.passed)
    .map((c) => `[${c.scope ?? "general"}][${c.severity}] ${c.message}`);

  let score = 100;
  for (const check of checks) {
    if (!check.passed) {
      if (check.severity === "error") score -= 25;
      if (check.severity === "warning") score -= 10;
      if (check.severity === "info") score -= 5;
    }
  }

  score = Math.max(0, score);

  return {
    score,
    checks,
    warnings,
  };
}
```

