# 3) Build the multi-run comparison runner

## `src/eval/comparePromptsMultiRun.ts`

```ts
import path from "node:path";
import { evalCases } from "./cases";
import { ensureDir, timestamp, writeJsonFile, writeTextFile } from "./utils";
import { generateBrainDumpPlanDebug } from "../lib/planning/service";
import {
  PROMPT_V1,
  PROMPT_V2,
  type PromptConfig,
} from "../lib/planning/prompts";
import { evaluateHeuristics } from "./heuristics";
import { aggregatePromptRuns } from "./aggregate";
import type {
  PromptRunResult,
  MultiRunCaseComparison,
  MultiRunComparisonSummary,
} from "./multiRunTypes";

const MODEL = process.env.OPENAI_MODEL || "gpt-4.1-mini";
const RUN_COUNT = Number(process.env.EVAL_RUN_COUNT || "3");
const OUTPUT_DIR = path.join(
  process.cwd(),
  "eval-comparisons-multirun",
  timestamp()
);

const PROMPTS_TO_COMPARE: PromptConfig[] = [PROMPT_V1, PROMPT_V2];

async function run() {
  console.log(
    `Running multi-run prompt comparison [${PROMPTS_TO_COMPARE.map((p) => p.version).join(", ")}] with model=${MODEL}, runs=${RUN_COUNT}`
  );

  await ensureDir(OUTPUT_DIR);

  const caseComparisons: MultiRunCaseComparison[] = [];

  for (const testCase of evalCases) {
    console.log(`\n→ ${testCase.id}: ${testCase.name}`);

    const promptRunsMap = new Map<string, PromptRunResult[]>();

    for (const promptConfig of PROMPTS_TO_COMPARE) {
      promptRunsMap.set(promptConfig.version, []);

      for (let runIndex = 1; runIndex <= RUN_COUNT; runIndex++) {
        const started = Date.now();

        try {
          const resultDebug = await generateBrainDumpPlanDebug({
            brainDump: testCase.brainDump,
            mode: "mixed",
            style: "direct",
            depth: "standard",
            promptConfig,
          });

          const durationMs = Date.now() - started;
          const heuristics = evaluateHeuristics(testCase, resultDebug.plan);

          const runResult: PromptRunResult = {
            runIndex,
            promptVersion: promptConfig.version,
            success: true,
            durationMs,
            output: resultDebug.plan,
            debug: {
              strictValidationPassed: resultDebug.debug.strictValidationPassed,
              normalizationUsed: resultDebug.debug.normalizationUsed,
              outputText: resultDebug.debug.outputText,
              parsedStructured: resultDebug.debug.parsedStructured,
              systemPrompt: resultDebug.debug.systemPrompt,
              userPrompt: resultDebug.debug.userPrompt,
            },
            heuristics,
          };

          promptRunsMap.get(promptConfig.version)?.push(runResult);

          console.log(
            `  ${promptConfig.version} run ${runIndex}/${RUN_COUNT}: success (${durationMs}ms) heuristic=${heuristics.score}`
          );
        } catch (error) {
          const durationMs = Date.now() - started;

          const runResult: PromptRunResult = {
            runIndex,
            promptVersion: promptConfig.version,
            success: false,
            durationMs,
            error: error instanceof Error ? error.message : "Unknown error",
          };

          promptRunsMap.get(promptConfig.version)?.push(runResult);

          console.log(
            `  ${promptConfig.version} run ${runIndex}/${RUN_COUNT}: failed (${durationMs}ms)`
          );
        }
      }
    }

    const promptAggregates = PROMPTS_TO_COMPARE.map((prompt) =>
      aggregatePromptRuns(
        prompt.version,
        promptRunsMap.get(prompt.version) ?? []
      )
    );

    const caseComparison: MultiRunCaseComparison = {
      caseId: testCase.id,
      caseName: testCase.name,
      category: testCase.category,
      brainDump: testCase.brainDump,
      promptAggregates,
    };

    caseComparisons.push(caseComparison);

    await writeJsonFile(
      path.join(OUTPUT_DIR, `${testCase.id}.multirun.json`),
      caseComparison
    );
  }

  const summary: MultiRunComparisonSummary = {
    model: MODEL,
    runCount: RUN_COUNT,
    comparedPromptVersions: PROMPTS_TO_COMPARE.map((p) => p.version),
    createdAt: new Date().toISOString(),
    totalCases: evalCases.length,
    cases: caseComparisons,
  };

  await writeJsonFile(path.join(OUTPUT_DIR, "multirun-summary.json"), summary);
  await writeTextFile(
    path.join(OUTPUT_DIR, "multirun-summary.md"),
    buildMarkdownSummary(summary)
  );
  await writeTextFile(
    path.join(OUTPUT_DIR, "multirun-scoring.csv"),
    buildScoringCsv(summary)
  );

  console.log(`\nDone. Multi-run comparison written to:\n${OUTPUT_DIR}`);
}

function buildMarkdownSummary(summary: MultiRunComparisonSummary) {
  const lines: string[] = [];

  lines.push("# Multi-Run Prompt Comparison Summary");
  lines.push("");
  lines.push(`- Model: ${summary.model}`);
  lines.push(`- Prompt versions: ${summary.comparedPromptVersions.join(", ")}`);
  lines.push(`- Runs per prompt per case: ${summary.runCount}`);
  lines.push(`- Total cases: ${summary.totalCases}`);
  lines.push(`- Created at: ${summary.createdAt}`);
  lines.push("");

  lines.push("## Aggregate Overview");
  lines.push("");
  lines.push(
    "| Case | Prompt | Successes | Avg Heuristic | Min | Max | Avg Duration | Strict Passes | Normalized |"
  );
  lines.push("|---|---|---:|---:|---:|---:|---:|---:|---:|");

  for (const c of summary.cases) {
    for (const agg of c.promptAggregates) {
      lines.push(
        `| ${c.caseId} - ${c.caseName} | ${agg.promptVersion} | ${agg.successCount}/${agg.totalRuns} | ${agg.avgHeuristicScore.toFixed(1)} | ${agg.minHeuristicScore ?? ""} | ${agg.maxHeuristicScore ?? ""} | ${Math.round(agg.avgDurationMs)}ms | ${agg.strictValidationPassCount} | ${agg.normalizationUsedCount} |`
      );
    }
  }

  lines.push("");
  lines.push("## Heuristic Winner by Case");
  lines.push("");

  for (const c of summary.cases) {
    const sorted = [...c.promptAggregates].sort(
      (a, b) => b.avgHeuristicScore - a.avgHeuristicScore
    );

    if (sorted.length === 0) {
      lines.push(`- ${c.caseId} - ${c.caseName}: no results`);
      continue;
    }

    const best = sorted[0];
    lines.push(
      `- ${c.caseId} - ${c.caseName}: ${best.promptVersion} (avg ${best.avgHeuristicScore.toFixed(1)})`
    );
  }

  lines.push("");
  lines.push("## Frequent Failed Checks");
  lines.push("");

  for (const c of summary.cases) {
    lines.push(`### ${c.caseId} - ${c.caseName}`);
    lines.push("");

    for (const agg of c.promptAggregates) {
      const failedEntries = Object.entries(agg.failedCheckCounts).sort(
        (a, b) => b[1] - a[1]
      );

      lines.push(`- **${agg.promptVersion}**`);

      if (failedEntries.length === 0) {
        lines.push("  - No repeated failed checks");
        continue;
      }

      for (const [checkId, count] of failedEntries.slice(0, 8)) {
        lines.push(`  - ${checkId}: ${count}/${agg.totalRuns}`);
      }
    }

    lines.push("");
  }

  return lines.join("\n");
}

function buildScoringCsv(summary: MultiRunComparisonSummary) {
  const headers = [
    "caseId",
    "caseName",
    "category",
    "model",
    "promptVersion",
    "runCount",
    "successCount",
    "failureCount",
    "avgHeuristicScore",
    "minHeuristicScore",
    "maxHeuristicScore",
    "avgDurationMs",
    "strictValidationPassCount",
    "normalizationUsedCount",
    "topFailedCheckIds",
    "notes",
  ];

  const rows: string[] = [];

  for (const c of summary.cases) {
    for (const agg of c.promptAggregates) {
      const topFailedChecks = Object.entries(agg.failedCheckCounts)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 8)
        .map(([id, count]) => `${id}:${count}/${agg.totalRuns}`)
        .join(" | ");

      rows.push(
        [
          c.caseId,
          `"${c.caseName}"`,
          c.category,
          summary.model,
          agg.promptVersion,
          agg.totalRuns,
          agg.successCount,
          agg.failureCount,
          agg.avgHeuristicScore.toFixed(1),
          agg.minHeuristicScore ?? "",
          agg.maxHeuristicScore ?? "",
          Math.round(agg.avgDurationMs),
          agg.strictValidationPassCount,
          agg.normalizationUsedCount,
          `"${topFailedChecks.replace(/"/g, '""')}"`,
          '""',
        ].join(",")
      );
    }
  }

  return [headers.join(","), ...rows].join("\n");
}

run().catch((error) => {
  console.error("Multi-run prompt comparison crashed:", error);
  process.exit(1);
});
```

