# 2) Add overall aggregation helpers

## `src/eval/aggregateOverall.ts`

```ts
import type {
  MultiRunCaseComparison,
  OverallPromptAggregate,
  PromptCasePromptAggregate,
} from "./multiRunTypes";

function average(nums: number[]) {
  if (nums.length === 0) return 0;
  return nums.reduce((sum, n) => sum + n, 0) / nums.length;
}

function mergeCountMaps(maps: Record<string, number>[]) {
  const merged: Record<string, number> = {};

  for (const map of maps) {
    for (const [key, value] of Object.entries(map)) {
      merged[key] = (merged[key] ?? 0) + value;
    }
  }

  return merged;
}

function getCaseWinners(
  caseComparison: MultiRunCaseComparison
): { winners: string[]; topScore: number } {
  const sorted = [...caseComparison.promptAggregates].sort(
    (a, b) => b.avgHeuristicScore - a.avgHeuristicScore
  );

  if (sorted.length === 0) {
    return { winners: [], topScore: 0 };
  }

  const topScore = sorted[0].avgHeuristicScore;
  const winners = sorted
    .filter((agg) => agg.avgHeuristicScore === topScore)
    .map((agg) => agg.promptVersion);

  return { winners, topScore };
}

export function aggregateOverallPromptResults(
  cases: MultiRunCaseComparison[],
  promptVersions: string[]
): OverallPromptAggregate[] {
  return promptVersions.map((promptVersion) => {
    const aggregatesForPrompt: PromptCasePromptAggregate[] = cases
      .map((c) =>
        c.promptAggregates.find((agg) => agg.promptVersion === promptVersion)
      )
      .filter((agg): agg is PromptCasePromptAggregate => Boolean(agg));

    const totalCases = aggregatesForPrompt.length;
    const totalRuns = aggregatesForPrompt.reduce((sum, agg) => sum + agg.totalRuns, 0);
    const successCount = aggregatesForPrompt.reduce(
      (sum, agg) => sum + agg.successCount,
      0
    );
    const failureCount = aggregatesForPrompt.reduce(
      (sum, agg) => sum + agg.failureCount,
      0
    );
    const strictValidationPassCount = aggregatesForPrompt.reduce(
      (sum, agg) => sum + agg.strictValidationPassCount,
      0
    );
    const normalizationUsedCount = aggregatesForPrompt.reduce(
      (sum, agg) => sum + agg.normalizationUsedCount,
      0
    );

    const heuristicScores = aggregatesForPrompt
      .flatMap((agg) =>
        agg.runs
          .filter((run) => run.success && typeof run.heuristics?.score === "number")
          .map((run) => run.heuristics!.score)
      );

    const durations = aggregatesForPrompt.flatMap((agg) =>
      agg.runs.map((run) => run.durationMs)
    );

    let caseWinCount = 0;
    let tiedCaseCount = 0;

    for (const caseComparison of cases) {
      const { winners } = getCaseWinners(caseComparison);
      if (winners.includes(promptVersion)) {
        if (winners.length === 1) {
          caseWinCount += 1;
        } else {
          tiedCaseCount += 1;
        }
      }
    }

    return {
      promptVersion,
      totalCases,
      totalRuns,
      successCount,
      failureCount,
      successRate: totalRuns > 0 ? successCount / totalRuns : 0,
      caseWinCount,
      tiedCaseCount,
      strictValidationPassCount,
      normalizationUsedCount,
      avgDurationMs: average(durations),
      avgHeuristicScore: average(heuristicScores),
      minHeuristicScore: heuristicScores.length
        ? Math.min(...heuristicScores)
        : null,
      maxHeuristicScore: heuristicScores.length
        ? Math.max(...heuristicScores)
        : null,
      failedCheckCounts: mergeCountMaps(
        aggregatesForPrompt.map((agg) => agg.failedCheckCounts)
      ),
      warningCounts: mergeCountMaps(
        aggregatesForPrompt.map((agg) => agg.warningCounts)
      ),
    };
  });
}
```

