  lines.push(`- Created at: ${summary.createdAt}`);
  lines.push("");

  lines.push("## Overall Prompt Summary");
  lines.push("");
  lines.push(
    "| Prompt | Success Rate | Avg Heuristic | Min | Max | Avg Duration | Case Wins | Ties | Strict Passes | Normalized |"
  );
  lines.push("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|");

  for (const overall of summary.overallPromptAggregates) {
    lines.push(
      `| ${overall.promptVersion} | ${(overall.successRate * 100).toFixed(1)}% (${overall.successCount}/${overall.totalRuns}) | ${overall.avgHeuristicScore.toFixed(1)} | ${overall.minHeuristicScore ?? ""} | ${overall.maxHeuristicScore ?? ""} | ${Math.round(overall.avgDurationMs)}ms | ${overall.caseWinCount} | ${overall.tiedCaseCount} | ${overall.strictValidationPassCount} | ${overall.normalizationUsedCount} |`
    );
  }

  lines.push("");
  lines.push("## Overall Frequent Failed Checks");
  lines.push("");

  for (const overall of summary.overallPromptAggregates) {
    lines.push(`### ${overall.promptVersion}`);
    lines.push("");

    const failedEntries = Object.entries(overall.failedCheckCounts).sort(
      (a, b) => b[1] - a[1]
    );

    if (failedEntries.length === 0) {
      lines.push("- No repeated failed checks");
    } else {
      for (const [checkId, count] of failedEntries.slice(0, 10)) {
        lines.push(`- ${checkId}: ${count}`);
      }
    }

    lines.push("");
  }

  lines.push("## Aggregate Overview by Case");
  lines.push("");
  lines.push(
    "| Case | Prompt | Successes | Avg Heuristic | Min | Max | Avg Duration | Strict Passes | Normalized |"
  );
  lines.push("|---|---|---:|---:|---:|---:|---:|---:|---:|");

  for (const c of summary.cases) {
    for (const agg of c.promptAggregates) {
      lines.push(
        `| ${c.caseId} - ${c.caseName} | ${agg.promptVersion} | ${agg.successCount}/${agg.totalRuns} | ${agg.avgHeuristicScore.toFixed(1)} | ${agg.minHeuristicScore ?? ""} | ${agg.maxHeuristicScore ?? ""} | ${Math.round(agg.avgDurationMs)}ms | ${agg.strictValidationPassCount} | ${agg.normalizationUsedCount} |`
      );
    }
  }

  lines.push("");
  lines.push("## Heuristic Winner by Case");
  lines.push("");

  for (const c of summary.cases) {
    const sorted = [...c.promptAggregates].sort(
      (a, b) => b.avgHeuristicScore - a.avgHeuristicScore
    );

    if (sorted.length === 0) {
      lines.push(`- ${c.caseId} - ${c.caseName}: no results`);
      continue;
    }

    const topScore = sorted[0].avgHeuristicScore;
    const winners = sorted.filter((agg) => agg.avgHeuristicScore === topScore);

    if (winners.length === 1) {
      lines.push(
        `- ${c.caseId} - ${c.caseName}: ${winners[0].promptVersion} (avg ${winners[0].avgHeuristicScore.toFixed(1)})`
      );
    } else {
      lines.push(
        `- ${c.caseId} - ${c.caseName}: tie (${winners
          .map((w) => w.promptVersion)
          .join(", ")}) at avg ${topScore.toFixed(1)}`
      );
    }
  }

  lines.push("");
  lines.push("## Frequent Failed Checks by Case");
  lines.push("");

  for (const c of summary.cases) {
    lines.push(`### ${c.caseId} - ${c.caseName}`);
    lines.push("");

    for (const agg of c.promptAggregates) {
      const failedEntries = Object.entries(agg.failedCheckCounts).sort(
        (a, b) => b[1] - a[1]
      );

      lines.push(`- **${agg.promptVersion}**`);

      if (failedEntries.length === 0) {
        lines.push("  - No repeated failed checks");
        continue;
      }

      for (const [checkId, count] of failedEntries.slice(0, 8)) {
        lines.push(`  - ${checkId}: ${count}/${agg.totalRuns}`);
      }
    }

    lines.push("");
  }

  return lines.join("\n");
}
