# 2) Add reusable stats helpers

Let’s centralize the math.

## `src/eval/stats.ts`

```ts
export function average(nums: number[]) {
  if (nums.length === 0) return 0;
  return nums.reduce((sum, n) => sum + n, 0) / nums.length;
}

export function stddev(nums: number[]) {
  if (nums.length === 0) return 0;
  const avg = average(nums);
  const variance =
    nums.reduce((sum, n) => sum + Math.pow(n - avg, 2), 0) / nums.length;
  return Math.sqrt(variance);
}

export function stabilityLabelFromStdDev(
  value: number
): "high" | "medium" | "low" {
  if (value <= 5) return "high";
  if (value <= 12) return "medium";
  return "low";
}
```

These thresholds are simple and practical for a 0–100 heuristic score.

You can tune them later.

