    );
    const normalizationUsedCount = aggregatesForPrompt.reduce(
      (sum, agg) => sum + agg.normalizationUsedCount,
      0
    );

    const heuristicScores = aggregatesForPrompt.flatMap((agg) =>
      agg.runs
        .filter((run) => run.success && typeof run.heuristics?.score === "number")
        .map((run) => run.heuristics!.score)
    );

    const durations = aggregatesForPrompt.flatMap((agg) =>
      agg.runs.map((run) => run.durationMs)
    );

    let caseWinCount = 0;
    let tiedCaseCount = 0;

    for (const caseComparison of cases) {
      const { winners } = getCaseWinners(caseComparison);
      if (winners.includes(promptVersion)) {
        if (winners.length === 1) {
          caseWinCount += 1;
        } else {
          tiedCaseCount += 1;
        }
      }
    }

    const heuristicStdDev = stddev(heuristicScores);

    return {
      promptVersion,
      totalCases,
      totalRuns,
      successCount,
      failureCount,
      successRate: totalRuns > 0 ? successCount / totalRuns : 0,
      caseWinCount,
      tiedCaseCount,
      strictValidationPassCount,
      normalizationUsedCount,
      avgDurationMs: average(durations),
      avgHeuristicScore: average(heuristicScores),
      heuristicStdDev,
      stabilityLabel: stabilityLabelFromStdDev(heuristicStdDev),
      minHeuristicScore: heuristicScores.length
        ? Math.min(...heuristicScores)
        : null,
      maxHeuristicScore: heuristicScores.length
        ? Math.max(...heuristicScores)
        : null,
      failedCheckCounts: mergeCountMaps(
        aggregatesForPrompt.map((agg) => agg.failedCheckCounts)
      ),
      warningCounts: mergeCountMaps(
        aggregatesForPrompt.map((agg) => agg.warningCounts)
      ),
    };
  });
}
