# 3) Add model aggregation helpers

## `src/eval/aggregateModels.ts`

```ts
import type {
  ModelRunResult,
  ModelCaseAggregate,
  ModelCaseComparison,
  OverallModelAggregate,
} from "./modelCompareTypes";
import { average, stddev, stabilityLabelFromStdDev } from "./stats";

function countBy(items: string[]) {
  const map: Record<string, number> = {};
  for (const item of items) {
    map[item] = (map[item] ?? 0) + 1;
  }
  return map;
}

function mergeCountMaps(maps: Record<string, number>[]) {
  const merged: Record<string, number> = {};

  for (const map of maps) {
    for (const [key, value] of Object.entries(map)) {
      merged[key] = (merged[key] ?? 0) + value;
    }
  }

  return merged;
}

export function aggregateModelRuns(
  model: string,
  promptVersion: string,
  runs: ModelRunResult[]
): ModelCaseAggregate {
  const successRuns = runs.filter((r) => r.success);
  const scores = successRuns
    .map((r) => r.heuristics?.score)
    .filter((v): v is number => typeof v === "number");

  const failedCheckIds = successRuns.flatMap((r) =>
    (r.heuristics?.checks ?? []).filter((c) => !c.passed).map((c) => c.id)
  );

  const warnings = successRuns.flatMap((r) => r.heuristics?.warnings ?? []);
  const heuristicStdDev = stddev(scores);

  return {
    model,
    promptVersion,
    totalRuns: runs.length,
    successCount: successRuns.length,
    failureCount: runs.length - successRuns.length,
    strictValidationPassCount: successRuns.filter(
      (r) => r.debug?.strictValidationPassed
    ).length,
    normalizationUsedCount: successRuns.filter(
      (r) => r.debug?.normalizationUsed
    ).length,
    avgDurationMs: average(runs.map((r) => r.durationMs)),
    avgHeuristicScore: average(scores),
    heuristicStdDev,
    stabilityLabel: stabilityLabelFromStdDev(heuristicStdDev),
    minHeuristicScore: scores.length ? Math.min(...scores) : null,
    maxHeuristicScore: scores.length ? Math.max(...scores) : null,
    failedCheckCounts: countBy(failedCheckIds),
    warningCounts: countBy(warnings),
    runs,
  };
}

function getCaseWinners(caseComparison: ModelCaseComparison) {
  const sorted = [...caseComparison.aggregates].sort(
    (a, b) => b.avgHeuristicScore - a.avgHeuristicScore
  );

  if (sorted.length === 0) {
    return { winners: [], topScore: 0 };
  }

  const topScore = sorted[0].avgHeuristicScore;
  const winners = sorted
    .filter((agg) => agg.avgHeuristicScore === topScore)
    .map((agg) => agg.model);

  return { winners, topScore };
}

export function aggregateOverallModelResults(
  cases: ModelCaseComparison[],
  models: string[],
  promptVersion: string
): OverallModelAggregate[] {
  return models.map((model) => {
    const aggregatesForModel = cases
      .map((c) => c.aggregates.find((agg) => agg.model === model))
      .filter((agg): agg is ModelCaseAggregate => Boolean(agg));

    const totalCases = aggregatesForModel.length;
    const totalRuns = aggregatesForModel.reduce((sum, agg) => sum + agg.totalRuns, 0);
    const successCount = aggregatesForModel.reduce(
      (sum, agg) => sum + agg.successCount,
      0
    );
    const failureCount = aggregatesForModel.reduce(
      (sum, agg) => sum + agg.failureCount,
      0
    );
    const strictValidationPassCount = aggregatesForModel.reduce(
      (sum, agg) => sum + agg.strictValidationPassCount,
      0
    );
    const normalizationUsedCount = aggregatesForModel.reduce(
      (sum, agg) => sum + agg.normalizationUsedCount,
      0
    );

    const scores = aggregatesForModel.flatMap((agg) =>
      agg.runs
        .filter((run) => run.success && typeof run.heuristics?.score === "number")
        .map((run) => run.heuristics!.score)
    );

    const durations = aggregatesForModel.flatMap((agg) =>
      agg.runs.map((run) => run.durationMs)
    );

    let caseWinCount = 0;
    let tiedCaseCount = 0;

    for (const caseComparison of cases) {
      const { winners } = getCaseWinners(caseComparison);
      if (winners.includes(model)) {
        if (winners.length === 1) caseWinCount += 1;
        else tiedCaseCount += 1;
      }
    }

    const heuristicStdDev = stddev(scores);

    return {
      model,
      promptVersion,
      totalCases,
      totalRuns,
      successCount,
      failureCount,
      successRate: totalRuns > 0 ? successCount / totalRuns : 0,
      caseWinCount,
      tiedCaseCount,
      strictValidationPassCount,
      normalizationUsedCount,
      avgDurationMs: average(durations),
      avgHeuristicScore: average(scores),
      heuristicStdDev,
      stabilityLabel: stabilityLabelFromStdDev(heuristicStdDev),
      minHeuristicScore: scores.length ? Math.min(...scores) : null,
      maxHeuristicScore: scores.length ? Math.max(...scores) : null,
      failedCheckCounts: mergeCountMaps(
        aggregatesForModel.map((agg) => agg.failedCheckCounts)
      ),
      warningCounts: mergeCountMaps(
        aggregatesForModel.map((agg) => agg.warningCounts)
      ),
    };
  });
}
```

