# 4) Build the multi-run model comparison runner

## `src/eval/compareModelsMultiRun.ts`

```ts
import path from "node:path";
import { evalCases } from "./cases";
import { ensureDir, timestamp, writeJsonFile, writeTextFile } from "./utils";
import { generateBrainDumpPlanDebug } from "../lib/planning/service";
import { PROMPT_V2 } from "../lib/planning/prompts";
import { evaluateHeuristics } from "./heuristics";
import {
  aggregateModelRuns,
  aggregateOverallModelResults,
} from "./aggregateModels";
import type {
  ModelRunResult,
  ModelCaseComparison,
  MultiRunModelComparisonSummary,
} from "./modelCompareTypes";

const RUN_COUNT = Number(process.env.EVAL_RUN_COUNT || "3");
const OUTPUT_DIR = path.join(
  process.cwd(),
  "eval-model-comparisons",
  timestamp()
);

const MODELS_TO_COMPARE = (
  process.env.EVAL_MODELS ||
  "gpt-4.1-mini,gpt-4.1"
)
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);

async function run() {
  console.log(
    `Running model comparison [${MODELS_TO_COMPARE.join(", ")}] with prompt=${PROMPT_V2.version}, runs=${RUN_COUNT}`
  );

  await ensureDir(OUTPUT_DIR);

  const caseComparisons: ModelCaseComparison[] = [];

  for (const testCase of evalCases) {
    console.log(`\n→ ${testCase.id}: ${testCase.name}`);

    const modelRunsMap = new Map<string, ModelRunResult[]>();

    for (const model of MODELS_TO_COMPARE) {
      modelRunsMap.set(model, []);

      for (let runIndex = 1; runIndex <= RUN_COUNT; runIndex++) {
        const started = Date.now();

        try {
          const resultDebug = await generateBrainDumpPlanDebug({
            brainDump: testCase.brainDump,
            mode: "mixed",
            style: "direct",
            depth: "standard",
            promptConfig: PROMPT_V2,
            modelOverride: model,
          });

          const durationMs = Date.now() - started;
          const heuristics = evaluateHeuristics(testCase, resultDebug.plan);

          const runResult: ModelRunResult = {
            runIndex,
            model,
            promptVersion: PROMPT_V2.version,
            success: true,
            durationMs,
            output: resultDebug.plan,
            debug: {
              strictValidationPassed: resultDebug.debug.strictValidationPassed,
              normalizationUsed: resultDebug.debug.normalizationUsed,
              outputText: resultDebug.debug.outputText,
              parsedStructured: resultDebug.debug.parsedStructured,
              systemPrompt: resultDebug.debug.systemPrompt,
              userPrompt: resultDebug.debug.userPrompt,
            },
            heuristics,
          };

          modelRunsMap.get(model)?.push(runResult);

          console.log(
            `  ${model} run ${runIndex}/${RUN_COUNT}: success (${durationMs}ms) heuristic=${heuristics.score}`
          );
        } catch (error) {
          const durationMs = Date.now() - started;

          const runResult: ModelRunResult = {
            runIndex,
            model,
            promptVersion: PROMPT_V2.version,
            success: false,
            durationMs,
            error: error instanceof Error ? error.message : "Unknown error",
          };

          modelRunsMap.get(model)?.push(runResult);

          console.log(
            `  ${model} run ${runIndex}/${RUN_COUNT}: failed (${durationMs}ms)`
          );
        }
      }
    }

    const aggregates = MODELS_TO_COMPARE.map((model) =>
      aggregateModelRuns(
        model,
        PROMPT_V2.version,
        modelRunsMap.get(model) ?? []
      )
    );

    const caseComparison: ModelCaseComparison = {
      caseId: testCase.id,
      caseName: testCase.name,
      category: testCase.category,
      brainDump: testCase.brainDump,
      aggregates,
    };

    caseComparisons.push(caseComparison);

    await writeJsonFile(
      path.join(OUTPUT_DIR, `${testCase.id}.models.json`),
      caseComparison
    );
  }

  const summary: MultiRunModelComparisonSummary = {
    promptVersion: PROMPT_V2.version,
    runCount: RUN_COUNT,
    comparedModels: MODELS_TO_COMPARE,
    createdAt: new Date().toISOString(),
    totalCases: evalCases.length,
    cases: caseComparisons,
    overallModelAggregates: aggregateOverallModelResults(
      caseComparisons,
      MODELS_TO_COMPARE,
      PROMPT_V2.version
    ),
  };

  await writeJsonFile(path.join(OUTPUT_DIR, "model-summary.json"), summary);
  await writeTextFile(
    path.join(OUTPUT_DIR, "model-summary.md"),
    buildMarkdownSummary(summary)
  );
  await writeTextFile(
    path.join(OUTPUT_DIR, "model-scoring.csv"),
    buildScoringCsv(summary)
  );

  console.log(`\nDone. Model comparison written to:\n${OUTPUT_DIR}`);
}

function buildMarkdownSummary(summary: MultiRunModelComparisonSummary) {
  const lines: string[] = [];

  lines.push("# Multi-Run Model Comparison Summary");
  lines.push("");
  lines.push(`- Prompt version: ${summary.promptVersion}`);
  lines.push(`- Models: ${summary.comparedModels.join(", ")}`);
  lines.push(`- Runs per model per case: ${summary.runCount}`);
  lines.push(`- Total cases: ${summary.totalCases}`);
  lines.push(`- Created at: ${summary.createdAt}`);
  lines.push("");

  lines.push("## Overall Model Summary");
  lines.push("");
  lines.push(
    "| Model | Success Rate | Avg Score | StdDev | Stability | Min | Max | Avg Duration | Case Wins | Ties | Strict Passes | Normalized |"
  );
  lines.push("|---|---:|---:|---:|---|---:|---:|---:|---:|---:|---:|---:|");

  for (const overall of summary.overallModelAggregates) {
    lines.push(
      `| ${overall.model} | ${(overall.successRate * 100).toFixed(1)}% (${overall.successCount}/${overall.totalRuns}) | ${overall.avgHeuristicScore.toFixed(1)} | ${overall.heuristicStdDev.toFixed(1)} | ${overall.stabilityLabel} | ${overall.minHeuristicScore ?? ""} | ${overall.maxHeuristicScore ?? ""} | ${Math.round(overall.avgDurationMs)}ms | ${overall.caseWinCount} | ${overall.tiedCaseCount} | ${overall.strictValidationPassCount} | ${overall.normalizationUsedCount} |`
    );
  }

  lines.push("");
  lines.push("## Overall Frequent Failed Checks");
  lines.push("");

  for (const overall of summary.overallModelAggregates) {
    lines.push(`### ${overall.model}`);
    lines.push("");

    const failedEntries = Object.entries(overall.failedCheckCounts).sort(
      (a, b) => b[1] - a[1]
    );

    if (failedEntries.length === 0) {
      lines.push("- No repeated failed checks");
    } else {
      for (const [checkId, count] of failedEntries.slice(0, 10)) {
        lines.push(`- ${checkId}: ${count}`);
      }
    }

    lines.push("");
  }

  lines.push("## Aggregate Overview by Case");
  lines.push("");
  lines.push(
    "| Case | Model | Successes | Avg Score | StdDev | Stability | Min | Max | Avg Duration | Strict Passes | Normalized |"
  );
  lines.push("|---|---|---:|---:|---:|---|---:|---:|---:|---:|---:|");

  for (const c of summary.cases) {
    for (const agg of c.aggregates) {
      lines.push(
        `| ${c.caseId} - ${c.caseName} | ${agg.model} | ${agg.successCount}/${agg.totalRuns} | ${agg.avgHeuristicScore.toFixed(1)} | ${agg.heuristicStdDev.toFixed(1)} | ${agg.stabilityLabel} | ${agg.minHeuristicScore ?? ""} | ${agg.maxHeuristicScore ?? ""} | ${Math.round(agg.avgDurationMs)}ms | ${agg.strictValidationPassCount} | ${agg.normalizationUsedCount} |`
      );
    }
  }

  lines.push("");
  lines.push("## Model Winner by Case");
  lines.push("");

  for (const c of summary.cases) {
    const sorted = [...c.aggregates].sort(
      (a, b) => b.avgHeuristicScore - a.avgHeuristicScore
    );

    if (sorted.length === 0) {
      lines.push(`- ${c.caseId} - ${c.caseName}: no results`);
      continue;
    }

    const topScore = sorted[0].avgHeuristicScore;
    const winners = sorted.filter((agg) => agg.avgHeuristicScore === topScore);

    if (winners.length === 1) {
      lines.push(
        `- ${c.caseId} - ${c.caseName}: ${winners[0].model} (avg ${winners[0].avgHeuristicScore.toFixed(1)}, stddev ${winners[0].heuristicStdDev.toFixed(1)})`
      );
    } else {
      lines.push(
        `- ${c.caseId} - ${c.caseName}: tie (${winners
          .map((w) => w.model)
          .join(", ")}) at avg ${topScore.toFixed(1)}`
      );
    }
  }

  return lines.join("\n");
}

function buildScoringCsv(summary: MultiRunModelComparisonSummary) {
  const headers = [
    "scope",
    "caseId",
    "caseName",
    "category",
    "promptVersion",
    "model",
    "runCount",
    "successCount",
    "failureCount",
    "successRate",
    "avgHeuristicScore",
    "heuristicStdDev",
    "stabilityLabel",
    "minHeuristicScore",
    "maxHeuristicScore",
    "avgDurationMs",
    "caseWinCount",
    "tiedCaseCount",
    "strictValidationPassCount",
    "normalizationUsedCount",
    "topFailedCheckIds",
    "notes",
  ];

  const rows: string[] = [];

  for (const overall of summary.overallModelAggregates) {
    const topFailedChecks = Object.entries(overall.failedCheckCounts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([id, count]) => `${id}:${count}`)
      .join(" | ");

    rows.push(
      [
        "overall",
        "",
        '""',
        "",
        summary.promptVersion,
        overall.model,
        overall.totalRuns,
        overall.successCount,
        overall.failureCount,
        overall.successRate.toFixed(3),
        overall.avgHeuristicScore.toFixed(1),
        overall.heuristicStdDev.toFixed(1),
        overall.stabilityLabel,
        overall.minHeuristicScore ?? "",
        overall.maxHeuristicScore ?? "",
        Math.round(overall.avgDurationMs),
        overall.caseWinCount,
        overall.tiedCaseCount,
        overall.strictValidationPassCount,
        overall.normalizationUsedCount,
        `"${topFailedChecks.replace(/"/g, '""')}"`,
        '""',
      ].join(",")
    );
  }

  for (const c of summary.cases) {
    for (const agg of c.aggregates) {
      const topFailedChecks = Object.entries(agg.failedCheckCounts)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 8)
        .map(([id, count]) => `${id}:${count}/${agg.totalRuns}`)
        .join(" | ");

      rows.push(
        [
          "case",
          c.caseId,
          `"${c.caseName}"`,
          c.category,
          summary.promptVersion,
          agg.model,
          agg.totalRuns,
          agg.successCount,
          agg.failureCount,
          (agg.totalRuns > 0 ? agg.successCount / agg.totalRuns : 0).toFixed(3),
          agg.avgHeuristicScore.toFixed(1),
          agg.heuristicStdDev.toFixed(1),
          agg.stabilityLabel,
          agg.minHeuristicScore ?? "",
          agg.maxHeuristicScore ?? "",
          Math.round(agg.avgDurationMs),
          "",
          "",
          agg.strictValidationPassCount,
          agg.normalizationUsedCount,
          `"${topFailedChecks.replace(/"/g, '""')}"`,
          '""',
        ].join(",")
      );
    }
  }

  return [headers.join(","), ...rows].join("\n");
}

run().catch((error) => {
  console.error("Multi-run model comparison crashed:", error);
  process.exit(1);
});
