# 2) Add token + cost estimation helpers

## `src/eval/costs.ts`

```ts
import { MODEL_PRICING_USD_PER_1M_TOKENS } from "./pricing";

export type TokenEstimate = {
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
};

export type CostEstimate = TokenEstimate & {
  estimatedCostUsd: number;
};

function estimateTokensFromText(text: string): number {
  // Rough heuristic: ~4 chars/token in English-ish text.
  // Good enough for eval comparisons.
  return Math.ceil(text.length / 4);
}

export function estimateTokenUsage(params: {
  systemPrompt: string;
  userPrompt: string;
  outputText: string;
}): TokenEstimate {
  const inputTokens =
    estimateTokensFromText(params.systemPrompt) +
    estimateTokensFromText(params.userPrompt);

  const outputTokens = estimateTokensFromText(params.outputText);

  return {
    inputTokens,
    outputTokens,
    totalTokens: inputTokens + outputTokens,
  };
}

export function estimateCostUsd(params: {
  model: string;
  inputTokens: number;
  outputTokens: number;
}): number {
  const pricing = MODEL_PRICING_USD_PER_1M_TOKENS[params.model];

  if (!pricing) {
    return 0;
  }

  const inputCost = (params.inputTokens / 1_000_000) * pricing.inputPer1M;
  const outputCost = (params.outputTokens / 1_000_000) * pricing.outputPer1M;

  return inputCost + outputCost;
}

export function estimateUsageAndCost(params: {
  model: string;
  systemPrompt: string;
  userPrompt: string;
  outputText: string;
}): CostEstimate {
  const tokens = estimateTokenUsage({
    systemPrompt: params.systemPrompt,
    userPrompt: params.userPrompt,
    outputText: params.outputText,
  });

  return {
    ...tokens,
    estimatedCostUsd: estimateCostUsd({
      model: params.model,
      inputTokens: tokens.inputTokens,
      outputTokens: tokens.outputTokens,
    }),
  };
}
```

