  lines.push(`- Created at: ${summary.createdAt}`);
  lines.push("");

  lines.push("## Overall Model Summary");
  lines.push("");
  lines.push(
    "| Model | Success Rate | Avg Score | StdDev | Stability | Avg Duration | Avg Cost/Run | Total Cost | Quality/$ | Case Wins |"
  );
  lines.push("|---|---:|---:|---:|---|---:|---:|---:|---:|---:|");

  for (const overall of summary.overallModelAggregates) {
    lines.push(
      `| ${overall.model} | ${(overall.successRate * 100).toFixed(1)}% (${overall.successCount}/${overall.totalRuns}) | ${overall.avgHeuristicScore.toFixed(1)} | ${overall.heuristicStdDev.toFixed(1)} | ${overall.stabilityLabel} | ${Math.round(overall.avgDurationMs)}ms | $${overall.estimatedAvgCostPerRunUsd.toFixed(4)} | $${overall.estimatedTotalCostUsd.toFixed(4)} | ${overall.qualityPerDollar.toFixed(1)} | ${overall.caseWinCount} |`
    );
  }

  lines.push("");
  lines.push("## Overall Frequent Failed Checks");
  lines.push("");

  for (const overall of summary.overallModelAggregates) {
    lines.push(`### ${overall.model}`);
    lines.push("");

    const failedEntries = Object.entries(overall.failedCheckCounts).sort(
      (a, b) => b[1] - a[1]
    );

    if (failedEntries.length === 0) {
      lines.push("- No repeated failed checks");
    } else {
      for (const [checkId, count] of failedEntries.slice(0, 10)) {
        lines.push(`- ${checkId}: ${count}`);
      }
    }

    lines.push("");
  }

  lines.push("## Aggregate Overview by Case");
  lines.push("");
  lines.push(
    "| Case | Model | Successes | Avg Score | StdDev | Avg Duration | Avg Cost/Run |"
  );
  lines.push("|---|---|---:|---:|---:|---:|---:|");

  for (const c of summary.cases) {
    for (const agg of c.aggregates) {
      lines.push(
        `| ${c.caseId} - ${c.caseName} | ${agg.model} | ${agg.successCount}/${agg.totalRuns} | ${agg.avgHeuristicScore.toFixed(1)} | ${agg.heuristicStdDev.toFixed(1)} | ${Math.round(agg.avgDurationMs)}ms | $${agg.estimatedAvgCostPerRunUsd.toFixed(4)} |`
      );
    }
  }

  lines.push("");
  lines.push("## Model Winner by Case");
  lines.push("");

  for (const c of summary.cases) {
    const sorted = [...c.aggregates].sort(
      (a, b) => b.avgHeuristicScore - a.avgHeuristicScore
    );

    if (sorted.length === 0) {
      lines.push(`- ${c.caseId} - ${c.caseName}: no results`);
      continue;
    }

    const topScore = sorted[0].avgHeuristicScore;
    const winners = sorted.filter((agg) => agg.avgHeuristicScore === topScore);

    if (winners.length === 1) {
      lines.push(
        `- ${c.caseId} - ${c.caseName}: ${winners[0].model} (avg ${winners[0].avgHeuristicScore.toFixed(1)}, cost/run $${winners[0].estimatedAvgCostPerRunUsd.toFixed(4)})`
      );
    } else {
      lines.push(
        `- ${c.caseId} - ${c.caseName}: tie (${winners
          .map((w) => w.model)
          .join(", ")}) at avg ${topScore.toFixed(1)}`
      );
    }
  }

  return lines.join("\n");
}
