# 2) Add matrix aggregation helpers

## `src/eval/aggregateMatrix.ts`

```ts
import type {
  MatrixRunResult,
  MatrixCaseCombinationAggregate,
  MatrixCaseComparison,
  OverallMatrixAggregate,
} from "./matrixTypes";
import { average, stddev, stabilityLabelFromStdDev } from "./stats";

function countBy(items: string[]) {
  const map: Record<string, number> = {};
  for (const item of items) {
    map[item] = (map[item] ?? 0) + 1;
  }
  return map;
}

function mergeCountMaps(maps: Record<string, number>[]) {
  const merged: Record<string, number> = {};

  for (const map of maps) {
    for (const [key, value] of Object.entries(map)) {
      merged[key] = (merged[key] ?? 0) + value;
    }
  }

  return merged;
}

export function aggregateMatrixRuns(params: {
  model: string;
  promptVersion: string;
  runs: MatrixRunResult[];
}): MatrixCaseCombinationAggregate {
  const { model, promptVersion, runs } = params;

  const successRuns = runs.filter((r) => r.success);
  const scores = successRuns
    .map((r) => r.heuristics?.score)
    .filter((v): v is number => typeof v === "number");

  const failedCheckIds = successRuns.flatMap((r) =>
    (r.heuristics?.checks ?? []).filter((c) => !c.passed).map((c) => c.id)
  );

  const warnings = successRuns.flatMap((r) => r.heuristics?.warnings ?? []);

  const inputTokens = successRuns
    .map((r) => r.estimatedUsage?.inputTokens)
    .filter((v): v is number => typeof v === "number");

  const outputTokens = successRuns
    .map((r) => r.estimatedUsage?.outputTokens)
    .filter((v): v is number => typeof v === "number");

  const totalTokens = successRuns
    .map((r) => r.estimatedUsage?.totalTokens)
    .filter((v): v is number => typeof v === "number");

  const costs = successRuns
    .map((r) => r.estimatedUsage?.estimatedCostUsd)
    .filter((v): v is number => typeof v === "number");

  const heuristicStdDev = stddev(scores);

  return {
    model,
    promptVersion,
    totalRuns: runs.length,
    successCount: successRuns.length,
    failureCount: runs.length - successRuns.length,
    strictValidationPassCount: successRuns.filter(
      (r) => r.debug?.strictValidationPassed
    ).length,
    normalizationUsedCount: successRuns.filter(
      (r) => r.debug?.normalizationUsed
    ).length,
    avgDurationMs: average(runs.map((r) => r.durationMs)),
    avgHeuristicScore: average(scores),
    heuristicStdDev,
    stabilityLabel: stabilityLabelFromStdDev(heuristicStdDev),
    minHeuristicScore: scores.length ? Math.min(...scores) : null,
    maxHeuristicScore: scores.length ? Math.max(...scores) : null,
    avgInputTokens: average(inputTokens),
    avgOutputTokens: average(outputTokens),
    avgTotalTokens: average(totalTokens),
    estimatedTotalCostUsd: costs.reduce((sum, c) => sum + c, 0),
    estimatedAvgCostPerRunUsd: average(costs),
    failedCheckCounts: countBy(failedCheckIds),
    warningCounts: countBy(warnings),
    runs,
  };
}

function getCaseWinners(caseComparison: MatrixCaseComparison) {
  const sorted = [...caseComparison.aggregates].sort(
    (a, b) => b.avgHeuristicScore - a.avgHeuristicScore
  );

  if (sorted.length === 0) {
    return { winners: [], topScore: 0 };
  }

  const topScore = sorted[0].avgHeuristicScore;
  const winners = sorted
    .filter((agg) => agg.avgHeuristicScore === topScore)
    .map((agg) => `${agg.promptVersion}__${agg.model}`);

  return { winners, topScore };
}

export function aggregateOverallMatrixResults(
  cases: MatrixCaseComparison[],
  combinations: Array<{ promptVersion: string; model: string }>
): OverallMatrixAggregate[] {
  return combinations.map(({ promptVersion, model }) => {
    const key = `${promptVersion}__${model}`;

    const aggregates = cases
      .map((c) =>
        c.aggregates.find(
          (agg) =>
            agg.promptVersion === promptVersion && agg.model === model
        )
      )
      .filter((agg): agg is MatrixCaseCombinationAggregate => Boolean(agg));

    const totalCases = aggregates.length;
    const totalRuns = aggregates.reduce((sum, agg) => sum + agg.totalRuns, 0);
    const successCount = aggregates.reduce((sum, agg) => sum + agg.successCount, 0);
    const failureCount = aggregates.reduce((sum, agg) => sum + agg.failureCount, 0);
    const strictValidationPassCount = aggregates.reduce(
      (sum, agg) => sum + agg.strictValidationPassCount,
      0
    );
    const normalizationUsedCount = aggregates.reduce(
      (sum, agg) => sum + agg.normalizationUsedCount,
      0
    );

    const scores = aggregates.flatMap((agg) =>
      agg.runs
        .filter((run) => run.success && typeof run.heuristics?.score === "number")
        .map((run) => run.heuristics!.score)
    );

    const durations = aggregates.flatMap((agg) =>
      agg.runs.map((run) => run.durationMs)
    );

    const inputTokens = aggregates.flatMap((agg) =>
      agg.runs
        .map((run) => run.estimatedUsage?.inputTokens)
        .filter((v): v is number => typeof v === "number")
    );

    const outputTokens = aggregates.flatMap((agg) =>
      agg.runs
        .map((run) => run.estimatedUsage?.outputTokens)
        .filter((v): v is number => typeof v === "number")
    );

    const totalTokens = aggregates.flatMap((agg) =>
      agg.runs
        .map((run) => run.estimatedUsage?.totalTokens)
        .filter((v): v is number => typeof v === "number")
    );

    const costs = aggregates.flatMap((agg) =>
      agg.runs
        .map((run) => run.estimatedUsage?.estimatedCostUsd)
        .filter((v): v is number => typeof v === "number")
    );

    let caseWinCount = 0;
    let tiedCaseCount = 0;

    for (const caseComparison of cases) {
      const { winners } = getCaseWinners(caseComparison);
      if (winners.includes(key)) {
        if (winners.length === 1) caseWinCount += 1;
        else tiedCaseCount += 1;
      }
    }

    const heuristicStdDev = stddev(scores);
    const estimatedTotalCostUsd = costs.reduce((sum, c) => sum + c, 0);
    const estimatedAvgCostPerRunUsd = average(costs);

    return {
      model,
      promptVersion,
      totalCases,
      totalRuns,
      successCount,
      failureCount,
      successRate: totalRuns > 0 ? successCount / totalRuns : 0,
      caseWinCount,
      tiedCaseCount,
      strictValidationPassCount,
      normalizationUsedCount,
      avgDurationMs: average(durations),
      avgHeuristicScore: average(scores),
      heuristicStdDev,
      stabilityLabel: stabilityLabelFromStdDev(heuristicStdDev),
      minHeuristicScore: scores.length ? Math.min(...scores) : null,
      maxHeuristicScore: scores.length ? Math.max(...scores) : null,
      avgInputTokens: average(inputTokens),
      avgOutputTokens: average(outputTokens),
      avgTotalTokens: average(totalTokens),
      estimatedTotalCostUsd,
      estimatedAvgCostPerRunUsd,
      qualityPerDollar:
        estimatedTotalCostUsd > 0 ? average(scores) / estimatedTotalCostUsd : 0,
      failedCheckCounts: mergeCountMaps(
        aggregates.map((agg) => agg.failedCheckCounts)
      ),
      warningCounts: mergeCountMaps(
        aggregates.map((agg) => agg.warningCounts)
      ),
    };
  });
}
```

