# 3) Build the matrix runner

## `src/eval/compareMatrixMultiRun.ts`

```ts
import path from "node:path";
import { evalCases } from "./cases";
import { ensureDir, timestamp, writeJsonFile, writeTextFile } from "./utils";
import { generateBrainDumpPlanDebug } from "../lib/planning/service";
import {
  PROMPT_V1,
  PROMPT_V2,
  type PromptConfig,
} from "../lib/planning/prompts";
import { evaluateHeuristics } from "./heuristics";
import { estimateUsageAndCost } from "./costs";
import {
  aggregateMatrixRuns,
  aggregateOverallMatrixResults,
} from "./aggregateMatrix";
import type {
  MatrixRunResult,
  MatrixCaseComparison,
  MatrixComparisonSummary,
} from "./matrixTypes";

const RUN_COUNT = Number(process.env.EVAL_RUN_COUNT || "3");
const OUTPUT_DIR = path.join(
  process.cwd(),
  "eval-matrix-comparisons",
  timestamp()
);

const MODELS_TO_COMPARE = (
  process.env.EVAL_MODELS || "gpt-4.1-mini,gpt-4.1"
)
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);

const PROMPTS_TO_COMPARE: PromptConfig[] = [PROMPT_V1, PROMPT_V2];

async function run() {
  console.log(
    `Running matrix comparison with prompts=[${PROMPTS_TO_COMPARE
      .map((p) => p.version)
      .join(", ")}], models=[${MODELS_TO_COMPARE.join(", ")}], runs=${RUN_COUNT}`
  );

  await ensureDir(OUTPUT_DIR);

  const caseComparisons: MatrixCaseComparison[] = [];

  for (const testCase of evalCases) {
    console.log(`\n→ ${testCase.id}: ${testCase.name}`);

    const runMap = new Map<string, MatrixRunResult[]>();

    for (const promptConfig of PROMPTS_TO_COMPARE) {
      for (const model of MODELS_TO_COMPARE) {
        const key = `${promptConfig.version}__${model}`;
        runMap.set(key, []);

        for (let runIndex = 1; runIndex <= RUN_COUNT; runIndex++) {
          const started = Date.now();

          try {
            const resultDebug = await generateBrainDumpPlanDebug({
              brainDump: testCase.brainDump,
              mode: "mixed",
              style: "direct",
              depth: "standard",
              promptConfig,
              modelOverride: model,
            });

            const durationMs = Date.now() - started;
            const heuristics = evaluateHeuristics(testCase, resultDebug.plan);

            const estimatedUsage = estimateUsageAndCost({
              model,
              systemPrompt: resultDebug.debug.systemPrompt,
              userPrompt: resultDebug.debug.userPrompt,
              outputText: resultDebug.debug.outputText,
            });

            const runResult: MatrixRunResult = {
              runIndex,
              model,
              promptVersion: promptConfig.version,
              success: true,
              durationMs,
              output: resultDebug.plan,
              debug: {
                strictValidationPassed: resultDebug.debug.strictValidationPassed,
                normalizationUsed: resultDebug.debug.normalizationUsed,
                outputText: resultDebug.debug.outputText,
                parsedStructured: resultDebug.debug.parsedStructured,
                systemPrompt: resultDebug.debug.systemPrompt,
                userPrompt: resultDebug.debug.userPrompt,
              },
              heuristics,
              estimatedUsage,
            };

            runMap.get(key)?.push(runResult);

            console.log(
              `  ${promptConfig.version} + ${model} run ${runIndex}/${RUN_COUNT}: success (${durationMs}ms) heuristic=${heuristics.score} cost=$${estimatedUsage.estimatedCostUsd.toFixed(4)}`
            );
          } catch (error) {
            const durationMs = Date.now() - started;

            const runResult: MatrixRunResult = {
              runIndex,
              model,
              promptVersion: promptConfig.version,
              success: false,
              durationMs,
              error: error instanceof Error ? error.message : "Unknown error",
            };

            runMap.get(key)?.push(runResult);

            console.log(
              `  ${promptConfig.version} + ${model} run ${runIndex}/${RUN_COUNT}: failed (${durationMs}ms)`
            );
          }
        }
      }
    }

    const aggregates = PROMPTS_TO_COMPARE.flatMap((promptConfig) =>
      MODELS_TO_COMPARE.map((model) =>
        aggregateMatrixRuns({
          model,
          promptVersion: promptConfig.version,
          runs: runMap.get(`${promptConfig.version}__${model}`) ?? [],
        })
      )
    );

    const caseComparison: MatrixCaseComparison = {
      caseId: testCase.id,
      caseName: testCase.name,
      category: testCase.category,
      brainDump: testCase.brainDump,
      aggregates,
    };

    caseComparisons.push(caseComparison);

    await writeJsonFile(
      path.join(OUTPUT_DIR, `${testCase.id}.matrix.json`),
      caseComparison
    );
  }

  const combinations = PROMPTS_TO_COMPARE.flatMap((promptConfig) =>
    MODELS_TO_COMPARE.map((model) => ({
      promptVersion: promptConfig.version,
      model,
    }))
  );

  const summary: MatrixComparisonSummary = {
    comparedModels: MODELS_TO_COMPARE,
    comparedPromptVersions: PROMPTS_TO_COMPARE.map((p) => p.version),
    runCount: RUN_COUNT,
    createdAt: new Date().toISOString(),
    totalCases: evalCases.length,
    cases: caseComparisons,
    overallAggregates: aggregateOverallMatrixResults(
      caseComparisons,
      combinations
    ),
  };

  await writeJsonFile(path.join(OUTPUT_DIR, "matrix-summary.json"), summary);
  await writeTextFile(
    path.join(OUTPUT_DIR, "matrix-summary.md"),
    buildMarkdownSummary(summary)
  );
  await writeTextFile(
    path.join(OUTPUT_DIR, "matrix-scoring.csv"),
    buildCsvSummary(summary)
  );

  console.log(`\nDone. Matrix comparison written to:\n${OUTPUT_DIR}`);
}
