```ts
function buildMarkdownSummary(summary: MatrixComparisonSummary) {
  const lines: string[] = [];

  lines.push("# Multi-Run Prompt × Model Matrix Summary");
  lines.push("");
  lines.push(`- Prompts: ${summary.comparedPromptVersions.join(", ")}`);
  lines.push(`- Models: ${summary.comparedModels.join(", ")}`);
  lines.push(`- Runs per combination per case: ${summary.runCount}`);
  lines.push(`- Total cases: ${summary.totalCases}`);
  lines.push(`- Created at: ${summary.createdAt}`);
  lines.push("");

  lines.push("## Overall Combination Summary");
  lines.push("");
  lines.push(
    "| Prompt | Model | Success Rate | Avg Score | StdDev | Stability | Avg Duration | Avg Cost/Run | Total Cost | Quality/$ | Case Wins |"
  );
  lines.push("|---|---|---:|---:|---:|---|---:|---:|---:|---:|---:|");

  const sortedOverall = [...summary.overallAggregates].sort((a, b) => {
    if (b.avgHeuristicScore !== a.avgHeuristicScore) {
      return b.avgHeuristicScore - a.avgHeuristicScore;
    }
    return a.estimatedAvgCostPerRunUsd - b.estimatedAvgCostPerRunUsd;
  });

  for (const overall of sortedOverall) {
    lines.push(
      `| ${overall.promptVersion} | ${overall.model} | ${(overall.successRate * 100).toFixed(1)}% (${overall.successCount}/${overall.totalRuns}) | ${overall.avgHeuristicScore.toFixed(1)} | ${overall.heuristicStdDev.toFixed(1)} | ${overall.stabilityLabel} | ${Math.round(overall.avgDurationMs)}ms | $${overall.estimatedAvgCostPerRunUsd.toFixed(4)} | $${overall.estimatedTotalCostUsd.toFixed(4)} | ${overall.qualityPerDollar.toFixed(1)} | ${overall.caseWinCount} |`
    );
  }

  lines.push("");
  lines.push("## Best Combination by Case");
  lines.push("");

  for (const c of summary.cases) {
    const sorted = [...c.aggregates].sort((a, b) => {
      if (b.avgHeuristicScore !== a.avgHeuristicScore) {
        return b.avgHeuristicScore - a.avgHeuristicScore;
      }
      return a.estimatedAvgCostPerRunUsd - b.estimatedAvgCostPerRunUsd;
    });

    if (sorted.length === 0) {
      lines.push(`- ${c.caseId} - ${c.caseName}: no results`);
      continue;
    }

    const best = sorted[0];
    lines.push(
      `- ${c.caseId} - ${c.caseName}: ${best.promptVersion} + ${best.model} (avg ${best.avgHeuristicScore.toFixed(1)}, stddev ${best.heuristicStdDev.toFixed(1)}, cost/run $${best.estimatedAvgCostPerRunUsd.toFixed(4)})`
    );
  }

  lines.push("");
  lines.push("## Frequent Failed Checks by Combination");
  lines.push("");

  for (const overall of sortedOverall) {
    lines.push(`### ${overall.promptVersion} + ${overall.model}`);
    lines.push("");

    const failedEntries = Object.entries(overall.failedCheckCounts).sort(
      (a, b) => b[1] - a[1]
    );

    if (failedEntries.length === 0) {
      lines.push("- No repeated failed checks");
    } else {
      for (const [checkId, count] of failedEntries.slice(0, 10)) {
        lines.push(`- ${checkId}: ${count}`);
      }
    }

    lines.push("");
  }

  return lines.join("\n");
}
