          c.category,
          agg.promptVersion,
          agg.model,
          agg.totalRuns,
          agg.successCount,
          agg.failureCount,
          (agg.totalRuns > 0 ? agg.successCount / agg.totalRuns : 0).toFixed(3),
          agg.avgHeuristicScore.toFixed(1),
          agg.heuristicStdDev.toFixed(1),
          agg.stabilityLabel,
          Math.round(agg.avgDurationMs),
          Math.round(agg.avgInputTokens),
          Math.round(agg.avgOutputTokens),
          Math.round(agg.avgTotalTokens),
          agg.estimatedAvgCostPerRunUsd.toFixed(6),
          agg.estimatedTotalCostUsd.toFixed(6),
          "",
          "",
          "",
          agg.strictValidationPassCount,
          agg.normalizationUsedCount,
          `"${topFailedChecks.replace(/"/g, '""')}"`,
          '""',
        ].join(",")
      );
    }
  }

  return [headers.join(","), ...rows].join("\n");
}

