```ts
import type { MatrixComparisonSummary } from "./matrixTypes";
import type {
  EvalRegressionSnapshot,
  CombinationRegressionSummary,
} from "./regressionTypes";

export function toRegressionSnapshot(
  summary: MatrixComparisonSummary
): EvalRegressionSnapshot {
  const combinations: CombinationRegressionSummary[] = summary.overallAggregates.map(
    (agg) => ({
      promptVersion: agg.promptVersion,
      model: agg.model,
      successRate: agg.successRate,
      avgHeuristicScore: agg.avgHeuristicScore,
      heuristicStdDev: agg.heuristicStdDev,
      stabilityLabel: agg.stabilityLabel,
      avgDurationMs: agg.avgDurationMs,
      estimatedAvgCostPerRunUsd: agg.estimatedAvgCostPerRunUsd,
      caseWinCount: agg.caseWinCount,
      tiedCaseCount: agg.tiedCaseCount,
      strictValidationPassCount: agg.strictValidationPassCount,
      normalizationUsedCount: agg.normalizationUsedCount,
      topFailedCheckIds: Object.entries(agg.failedCheckCounts)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10)
        .map(([id, count]) => ({ id, count })),
    })
  );

  return {
    createdAt: summary.createdAt,
    runCount: summary.runCount,
    totalCases: summary.totalCases,
    combinations,
  };
}
