export type RegressionThresholds = {
  maxSuccessRateDrop: number; // absolute fraction, e.g. 0.05 = 5%
  maxAvgScoreDrop: number; // absolute heuristic points
  maxStdDevIncrease: number; // absolute heuristic points
  maxDurationIncreasePct: number; // e.g. 0.35 = 35%
  maxCostIncreasePct: number; // e.g. 0.50 = 50%
  maxCaseWinDrop: number; // integer count
  maxStrictValidationPassDrop: number; // integer count
  disallowNewTopFailedChecks?: string[]; // critical check IDs
};

export const DEFAULT_REGRESSION_THRESHOLDS: RegressionThresholds = {
  maxSuccessRateDrop: 0.05,
  maxAvgScoreDrop: 3,
  maxStdDevIncrease: 4,
  maxDurationIncreasePct: 0.35,
  maxCostIncreasePct: 0.5,
  maxCaseWinDrop: 2,
  maxStrictValidationPassDrop: 3,
  disallowNewTopFailedChecks: [
    "must_surface_enterprise_vs_selfserve",
    "must_notice_finance_jordan_or_legal_blockers",
    "must_not_hallucinate_jen_identity",
    "must_notice_sam_or_pricing_copy",
  ],
};
```

These are good starting defaults:
- not too jittery
- not too lax

You can tune them after a few runs.

