# 4) Build the baseline comparison script

## `src/eval/compareAgainstBaseline.ts`

```ts
import fs from "node:fs/promises";
import path from "node:path";
import type { EvalRegressionSnapshot } from "./regressionTypes";
import {
  DEFAULT_REGRESSION_THRESHOLDS,
  type RegressionThresholds,
} from "./regressionConfig";

type RegressionIssue = {
  severity: "warning" | "error";
  combinationKey: string;
  metric: string;
  baseline: number | string;
  current: number | string;
  message: string;
};

function combinationKey(promptVersion: string, model: string) {
  return `${promptVersion}__${model}`;
}

function pctIncrease(baseline: number, current: number) {
  if (baseline === 0) return current > 0 ? Infinity : 0;
  return (current - baseline) / baseline;
}

function topFailedCheckIds(snapshotItem: {
  topFailedCheckIds: Array<{ id: string; count: number }>;
}) {
  return new Set(snapshotItem.topFailedCheckIds.map((x) => x.id));
}

async function readJson<T>(filePath: string): Promise<T> {
  const raw = await fs.readFile(filePath, "utf8");
  return JSON.parse(raw) as T;
}

async function main() {
  const baselinePath =
    process.env.EVAL_BASELINE_PATH ||
    path.join(process.cwd(), "eval-baselines", "matrix-baseline.json");

  const currentPath =
    process.env.EVAL_CURRENT_PATH ||
    path.join(process.cwd(), "eval-matrix-comparisons", "latest-regression-snapshot.json");

  const thresholds: RegressionThresholds = DEFAULT_REGRESSION_THRESHOLDS;

  const baseline = await readJson<EvalRegressionSnapshot>(baselinePath);
  const current = await readJson<EvalRegressionSnapshot>(currentPath);

  const baselineMap = new Map(
    baseline.combinations.map((c) => [combinationKey(c.promptVersion, c.model), c])
  );

  const currentMap = new Map(
    current.combinations.map((c) => [combinationKey(c.promptVersion, c.model), c])
  );

  const issues: RegressionIssue[] = [];

  for (const [key, curr] of currentMap.entries()) {
    const base = baselineMap.get(key);

    if (!base) {
      issues.push({
        severity: "warning",
        combinationKey: key,
        metric: "new_combination",
        baseline: "",
        current: key,
        message: `New combination detected: ${key}. No baseline comparison available.`,
      });
      continue;
    }

    const successRateDrop = base.successRate - curr.successRate;
    if (successRateDrop > thresholds.maxSuccessRateDrop) {
      issues.push({
        severity: "error",
        combinationKey: key,
        metric: "successRate",
        baseline: base.successRate,
        current: curr.successRate,
        message: `Success rate dropped by ${(successRateDrop * 100).toFixed(1)} percentage points.`,
      });
    }

    const avgScoreDrop = base.avgHeuristicScore - curr.avgHeuristicScore;
    if (avgScoreDrop > thresholds.maxAvgScoreDrop) {
      issues.push({
        severity: "error",
        combinationKey: key,
        metric: "avgHeuristicScore",
        baseline: base.avgHeuristicScore,
        current: curr.avgHeuristicScore,
        message: `Average heuristic score dropped by ${avgScoreDrop.toFixed(1)} points.`,
      });
    }

    const stdDevIncrease = curr.heuristicStdDev - base.heuristicStdDev;
    if (stdDevIncrease > thresholds.maxStdDevIncrease) {
      issues.push({
        severity: "warning",
        combinationKey: key,
        metric: "heuristicStdDev",
        baseline: base.heuristicStdDev,
        current: curr.heuristicStdDev,
        message: `Heuristic stddev increased by ${stdDevIncrease.toFixed(1)}.`,
      });
    }

    const durationIncrease = pctIncrease(base.avgDurationMs, curr.avgDurationMs);
    if (durationIncrease > thresholds.maxDurationIncreasePct) {
      issues.push({
        severity: "warning",
        combinationKey: key,
        metric: "avgDurationMs",
        baseline: base.avgDurationMs,
        current: curr.avgDurationMs,
        message: `Average duration increased by ${(durationIncrease * 100).toFixed(1)}%.`,
      });
    }

    const costIncrease = pctIncrease(
      base.estimatedAvgCostPerRunUsd,
      curr.estimatedAvgCostPerRunUsd
    );
    if (costIncrease > thresholds.maxCostIncreasePct) {
      issues.push({
        severity: "warning",
        combinationKey: key,
        metric: "estimatedAvgCostPerRunUsd",
        baseline: base.estimatedAvgCostPerRunUsd,
        current: curr.estimatedAvgCostPerRunUsd,
        message: `Estimated cost per run increased by ${(costIncrease * 100).toFixed(1)}%.`,
      });
    }

    const caseWinDrop = base.caseWinCount - curr.caseWinCount;
    if (caseWinDrop > thresholds.maxCaseWinDrop) {
      issues.push({
        severity: "warning",
        combinationKey: key,
        metric: "caseWinCount",
        baseline: base.caseWinCount,
        current: curr.caseWinCount,
        message: `Case wins dropped by ${caseWinDrop}.`,
      });
    }

    const strictPassDrop =
      base.strictValidationPassCount - curr.strictValidationPassCount;
    if (strictPassDrop > thresholds.maxStrictValidationPassDrop) {
      issues.push({
        severity: "error",
        combinationKey: key,
        metric: "strictValidationPassCount",
        baseline: base.strictValidationPassCount,
        current: curr.strictValidationPassCount,
        message: `Strict validation pass count dropped by ${strictPassDrop}.`,
      });
    }

    const baseFailed = topFailedCheckIds(base);
    const currFailed = topFailedCheckIds(curr);

    for (const criticalCheck of thresholds.disallowNewTopFailedChecks ?? []) {
      if (!baseFailed.has(criticalCheck) && currFailed.has(criticalCheck)) {
        issues.push({
          severity: "error",
          combinationKey: key,
          metric: "newCriticalFailedCheck",
          baseline: "absent",
          current: criticalCheck,
          message: `New critical failed check appeared: ${criticalCheck}.`,
        });
      }
    }
  }

  const errorCount = issues.filter((i) => i.severity === "error").length;
  const warningCount = issues.filter((i) => i.severity === "warning").length;

  console.log(`# Regression Check`);
  console.log(`Baseline: ${baselinePath}`);
  console.log(`Current: ${currentPath}`);
  console.log(`Errors: ${errorCount}`);
  console.log(`Warnings: ${warningCount}`);
  console.log("");

  if (issues.length === 0) {
    console.log("No regression issues found.");
    process.exit(0);
  }

  for (const issue of issues) {
    console.log(
      `[${issue.severity.toUpperCase()}] ${issue.combinationKey} :: ${issue.metric} :: ${issue.message}`
    );
  }

  process.exit(errorCount > 0 ? 1 : 0);
}

main().catch((error) => {
  console.error("Regression comparison crashed:", error);
  process.exit(2);
});
```

