# 1) Add combo filter helpers

## `src/eval/comboFilter.ts`

```ts
export type Combo = {
  promptVersion: string;
  model: string;
};

export function comboKey(combo: Combo) {
  return `${combo.promptVersion}__${combo.model}`;
}

export function parsePrimaryComboFromEnv():
  | Combo
  | null {
  const raw = process.env.EVAL_PRIMARY_COMBO?.trim();

  if (!raw) return null;

  const [promptVersion, model] = raw.split("__").map((s) => s.trim());

  if (!promptVersion || !model) {
    throw new Error(
      `Invalid EVAL_PRIMARY_COMBO format. Expected "promptVersion__model", got "${raw}"`
    );
  }

  return { promptVersion, model };
}

export function filterCombos<T extends Combo>(
  combos: T[],
  primaryCombo: Combo | null
): T[] {
  if (!primaryCombo) return combos;

  return combos.filter(
    (combo) =>
      combo.promptVersion === primaryCombo.promptVersion &&
      combo.model === primaryCombo.model
  );
}
```

This gives you one consistent format:

```env
EVAL_PRIMARY_COMBO=v2__gpt-4.1-mini
```

