for (const combo of COMBINATIONS_TO_COMPARE) {
  const { promptConfig, model, promptVersion } = combo;
  const key = `${promptVersion}__${model}`;
  runMap.set(key, []);

  for (let runIndex = 1; runIndex <= RUN_COUNT; runIndex++) {
    const started = Date.now();

    try {
      const resultDebug = await generateBrainDumpPlanDebug({
        brainDump: testCase.brainDump,
        mode: "mixed",
        style: "direct",
        depth: "standard",
        promptConfig,
        modelOverride: model,
      });

      const durationMs = Date.now() - started;
      const heuristics = evaluateHeuristics(testCase, resultDebug.plan);

      const estimatedUsage = estimateUsageAndCost({
        model,
        systemPrompt: resultDebug.debug.systemPrompt,
        userPrompt: resultDebug.debug.userPrompt,
        outputText: resultDebug.debug.outputText,
      });

      const runResult: MatrixRunResult = {
        runIndex,
        model,
        promptVersion,
        success: true,
        durationMs,
        output: resultDebug.plan,
        debug: {
          strictValidationPassed: resultDebug.debug.strictValidationPassed,
          normalizationUsed: resultDebug.debug.normalizationUsed,
          outputText: resultDebug.debug.outputText,
          parsedStructured: resultDebug.debug.parsedStructured,
          systemPrompt: resultDebug.debug.systemPrompt,
          userPrompt: resultDebug.debug.userPrompt,
        },
        heuristics,
        estimatedUsage,
      };

      runMap.get(key)?.push(runResult);

      console.log(
        `  ${promptVersion} + ${model} run ${runIndex}/${RUN_COUNT}: success (${durationMs}ms) heuristic=${heuristics.score} cost=$${estimatedUsage.estimatedCostUsd.toFixed(4)}`
      );
    } catch (error) {
      const durationMs = Date.now() - started;

      const runResult: MatrixRunResult = {
        runIndex,
        model,
        promptVersion,
        success: false,
        durationMs,
        error: error instanceof Error ? error.message : "Unknown error",
      };

      runMap.get(key)?.push(runResult);

      console.log(
        `  ${promptVersion} + ${model} run ${runIndex}/${RUN_COUNT}: failed (${durationMs}ms)`
      );
    }
  }
}
