# 3) Expand regression snapshot generation

Update `src/eval/regressionConfig.ts`.

Replace with:

```ts
import type { MatrixComparisonSummary } from "./matrixTypes";
import type {
  EvalRegressionSnapshot,
  CombinationRegressionSummary,
  CaseCombinationRegressionSummary,
} from "./regressionTypes";

export type RegressionThresholds = {
  maxSuccessRateDrop: number;
  maxAvgScoreDrop: number;
  maxStdDevIncrease: number;
  maxDurationIncreasePct: number;
  maxCostIncreasePct: number;
  maxCaseWinDrop: number;
  maxStrictValidationPassDrop: number;
  disallowNewTopFailedChecks?: string[];
};

export const DEFAULT_REGRESSION_THRESHOLDS: RegressionThresholds = {
  maxSuccessRateDrop: 0.05,
  maxAvgScoreDrop: 3,
  maxStdDevIncrease: 4,
  maxDurationIncreasePct: 0.35,
  maxCostIncreasePct: 0.5,
  maxCaseWinDrop: 2,
  maxStrictValidationPassDrop: 3,
  disallowNewTopFailedChecks: [
    "must_surface_enterprise_vs_selfserve",
    "must_notice_finance_jordan_or_legal_blockers",
    "must_not_hallucinate_jen_identity",
    "must_notice_sam_or_pricing_copy",
  ],
};

export function toRegressionSnapshot(
  summary: MatrixComparisonSummary
): EvalRegressionSnapshot {
  const combinations: CombinationRegressionSummary[] = summary.overallAggregates.map(
    (agg) => ({
      promptVersion: agg.promptVersion,
      model: agg.model,
      successRate: agg.successRate,
      avgHeuristicScore: agg.avgHeuristicScore,
      heuristicStdDev: agg.heuristicStdDev,
      stabilityLabel: agg.stabilityLabel,
      avgDurationMs: agg.avgDurationMs,
      estimatedAvgCostPerRunUsd: agg.estimatedAvgCostPerRunUsd,
      caseWinCount: agg.caseWinCount,
      tiedCaseCount: agg.tiedCaseCount,
      strictValidationPassCount: agg.strictValidationPassCount,
      normalizationUsedCount: agg.normalizationUsedCount,
      topFailedCheckIds: Object.entries(agg.failedCheckCounts)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10)
        .map(([id, count]) => ({ id, count })),
    })
  );

  const caseCombinations: CaseCombinationRegressionSummary[] = summary.cases.flatMap(
    (caseSummary) =>
      caseSummary.aggregates.map((agg) => ({
        caseId: caseSummary.caseId,
        caseName: caseSummary.caseName,
        category: caseSummary.category,
        promptVersion: agg.promptVersion,
        model: agg.model,
        successRate: agg.totalRuns > 0 ? agg.successCount / agg.totalRuns : 0,
        avgHeuristicScore: agg.avgHeuristicScore,
        heuristicStdDev: agg.heuristicStdDev,
        stabilityLabel: agg.stabilityLabel,
        avgDurationMs: agg.avgDurationMs,
        estimatedAvgCostPerRunUsd: agg.estimatedAvgCostPerRunUsd,
        strictValidationPassCount: agg.strictValidationPassCount,
        normalizationUsedCount: agg.normalizationUsedCount,
        failedCheckIds: Object.entries(agg.failedCheckCounts)
          .sort((a, b) => b[1] - a[1])
          .map(([id, count]) => ({ id, count })),
      }))
  );

  return {
    createdAt: summary.createdAt,
    runCount: summary.runCount,
    totalCases: summary.totalCases,
    combinations,
    caseCombinations,
  };
}
```

