## After the overall-combination regression loop, add protected-case checks

```ts
for (const rule of PROTECTED_CASE_RULES) {
  for (const currentCase of filteredCurrentCaseCombinations.filter(
    (c) => c.caseId === rule.caseId
  )) {
    const key = caseCombinationKey({
      caseId: currentCase.caseId,
      promptVersion: currentCase.promptVersion,
      model: currentCase.model,
    });

    const baselineCase = baselineCaseMap.get(key);

    if (!baselineCase) {
      caseIssues.push({
        severity: "warning",
        combinationKey: comboKey({
          promptVersion: currentCase.promptVersion,
          model: currentCase.model,
        }),
        caseId: currentCase.caseId,
        metric: "missingBaselineCase",
        baseline: "",
        current: key,
        message: `No baseline case snapshot available for protected case ${currentCase.caseId}.`,
      });
      continue;
    }

    const severity = rule.severity ?? "error";

    if (
      typeof rule.minSuccessRate === "number" &&
      currentCase.successRate < rule.minSuccessRate
    ) {
      caseIssues.push({
        severity,
        combinationKey: comboKey({
          promptVersion: currentCase.promptVersion,
          model: currentCase.model,
        }),
        caseId: currentCase.caseId,
        metric: "minSuccessRate",
        baseline: baselineCase.successRate,
        current: currentCase.successRate,
        message: `Protected case ${currentCase.caseId} success rate fell below minimum ${rule.minSuccessRate.toFixed(2)}.`,
      });
    }

    if (
      typeof rule.maxAvgScoreDrop === "number" &&
      baselineCase.avgHeuristicScore - currentCase.avgHeuristicScore >
        rule.maxAvgScoreDrop
    ) {
      caseIssues.push({
        severity,
        combinationKey: comboKey({
          promptVersion: currentCase.promptVersion,
          model: currentCase.model,
        }),
        caseId: currentCase.caseId,
        metric: "avgHeuristicScore",
        baseline: baselineCase.avgHeuristicScore,
        current: currentCase.avgHeuristicScore,
        message: `Protected case ${currentCase.caseId} average score dropped by more than ${rule.maxAvgScoreDrop}.`,
      });
    }

    if (
      typeof rule.maxStdDevIncrease === "number" &&
      currentCase.heuristicStdDev - baselineCase.heuristicStdDev >
        rule.maxStdDevIncrease
    ) {
      caseIssues.push({
        severity,
        combinationKey: comboKey({
          promptVersion: currentCase.promptVersion,
          model: currentCase.model,
        }),
        caseId: currentCase.caseId,
        metric: "heuristicStdDev",
        baseline: baselineCase.heuristicStdDev,
        current: currentCase.heuristicStdDev,
        message: `Protected case ${currentCase.caseId} stddev increased too much.`,
      });
    }

    if (
      typeof rule.maxDurationIncreasePct === "number" &&
      pctIncrease(baselineCase.avgDurationMs, currentCase.avgDurationMs) >
        rule.maxDurationIncreasePct
    ) {
      caseIssues.push({
        severity: "warning",
        combinationKey: comboKey({
          promptVersion: currentCase.promptVersion,
          model: currentCase.model,
        }),
        caseId: currentCase.caseId,
        metric: "avgDurationMs",
        baseline: baselineCase.avgDurationMs,
        current: currentCase.avgDurationMs,
        message: `Protected case ${currentCase.caseId} duration increased too much.`,
      });
    }

    if (
      typeof rule.maxCostIncreasePct === "number" &&
      pctIncrease(
        baselineCase.estimatedAvgCostPerRunUsd,
        currentCase.estimatedAvgCostPerRunUsd
      ) > rule.maxCostIncreasePct
    ) {
      caseIssues.push({
        severity: "warning",
        combinationKey: comboKey({
          promptVersion: currentCase.promptVersion,
          model: currentCase.model,
        }),
        caseId: currentCase.caseId,
        metric: "estimatedAvgCostPerRunUsd",
        baseline: baselineCase.estimatedAvgCostPerRunUsd,
        current: currentCase.estimatedAvgCostPerRunUsd,
        message: `Protected case ${currentCase.caseId} cost increased too much.`,
      });
    }

    if (
      typeof rule.maxStrictValidationPassDrop === "number" &&
      baselineCase.strictValidationPassCount - currentCase.strictValidationPassCount >
        rule.maxStrictValidationPassDrop
    ) {
      caseIssues.push({
        severity,
        combinationKey: comboKey({
          promptVersion: currentCase.promptVersion,
          model: currentCase.model,
        }),
        caseId: currentCase.caseId,
        metric: "strictValidationPassCount",
        baseline: baselineCase.strictValidationPassCount,
        current: currentCase.strictValidationPassCount,
        message: `Protected case ${currentCase.caseId} strict validation pass count dropped too much.`,
      });
    }

    const currentFailedChecks = failedCheckSet(currentCase);

    for (const checkId of rule.disallowFailedChecks ?? []) {
      if (currentFailedChecks.has(checkId)) {
        caseIssues.push({
          severity,
          combinationKey: comboKey({
            promptVersion: currentCase.promptVersion,
            model: currentCase.model,
          }),
          caseId: currentCase.caseId,
          metric: "disallowFailedChecks",
          baseline: "allowed previously or not checked",
          current: checkId,
          message: `Protected case ${currentCase.caseId} is failing forbidden check ${checkId}.`,
        });
      }
    }

    for (const checkId of rule.requireChecksToStayAbsent ?? []) {
      if (currentFailedChecks.has(checkId)) {
        caseIssues.push({
          severity,
          combinationKey: comboKey({
            promptVersion: currentCase.promptVersion,
            model: currentCase.model,
          }),
          caseId: currentCase.caseId,
          metric: "requireChecksToStayAbsent",
          baseline: "absent expected",
          current: checkId,
          message: `Protected case ${currentCase.caseId} must keep check ${checkId} absent, but it is now failing.`,
        });
      }
    }
  }
}
```

