# 1) Add env/config helpers

## `src/eval/evalEnv.ts`

```ts
function parseNumber(value: string | undefined): number | undefined {
  if (value == null || value.trim() === "") return undefined;
  const n = Number(value);
  return Number.isFinite(n) ? n : undefined;
}

function parseStringList(value: string | undefined): string[] | undefined {
  if (!value || !value.trim()) return undefined;
  return value
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
}

function parseBoolean(value: string | undefined): boolean | undefined {
  if (!value || !value.trim()) return undefined;
  const lower = value.trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(lower)) return true;
  if (["0", "false", "no", "off"].includes(lower)) return false;
  return undefined;
}

export function getEvalMode(): "local" | "pr" | "ci" | "release" {
  const raw = process.env.EVAL_MODE?.trim().toLowerCase();

  if (raw === "pr" || raw === "ci" || raw === "release" || raw === "local") {
    return raw;
  }

  return "local";
}

export function getEnvThresholdOverrides() {
  return {
    maxSuccessRateDrop: parseNumber(process.env.EVAL_MAX_SUCCESS_RATE_DROP),
    maxAvgScoreDrop: parseNumber(process.env.EVAL_MAX_AVG_SCORE_DROP),
    maxStdDevIncrease: parseNumber(process.env.EVAL_MAX_STDDEV_INCREASE),
    maxDurationIncreasePct: parseNumber(process.env.EVAL_MAX_DURATION_INCREASE_PCT),
    maxCostIncreasePct: parseNumber(process.env.EVAL_MAX_COST_INCREASE_PCT),
    maxCaseWinDrop: parseNumber(process.env.EVAL_MAX_CASE_WIN_DROP),
    maxStrictValidationPassDrop: parseNumber(
      process.env.EVAL_MAX_STRICT_VALIDATION_PASS_DROP
    ),
    disallowNewTopFailedChecks: parseStringList(
      process.env.EVAL_DISALLOW_NEW_TOP_FAILED_CHECKS
    ),
  };
}

export function getProtectedCasesOverride(): string[] | undefined {
  return parseStringList(process.env.EVAL_PROTECTED_CASES);
}

export function getRunCountFromEnv(defaultValue: number): number {
  const parsed = parseNumber(process.env.EVAL_RUN_COUNT);
  return parsed ?? defaultValue;
}

export function getModelsFromEnv(defaultModels: string[]): string[] {
  const parsed = parseStringList(process.env.EVAL_MODELS);
  return parsed && parsed.length ? parsed : defaultModels;
}

export function getPromptsFromEnv(defaultPrompts: string[]): string[] {
  const parsed = parseStringList(process.env.EVAL_PROMPTS);
  return parsed && parsed.length ? parsed : defaultPrompts;
}

export function getFailOnWarnings(): boolean {
  return parseBoolean(process.env.EVAL_FAIL_ON_WARNINGS) ?? false;
}
```

