    description: "Overwhelm-heavy inputs must remain calming and low-overload.",
    maxAvgScoreDrop: 3,
    maxStdDevIncrease: 4,
    minSuccessRate: 0.95,
    disallowFailedChecks: [
      "should_limit_next_actions_for_overwhelm",
      "must_notice_application_or_taxes",
