      "must_treat_webinar_as_decision",
    ],
    severity: "error",
  },
];

export function getProtectedCaseRules(): ProtectedCaseRule[] {
  const mode = getEvalMode();
  const envOverride = getProtectedCasesOverride();

  const baseRules =
    mode === "release"
      ? RELEASE_PROTECTED_CASE_RULES
      : DEFAULT_PROTECTED_CASE_RULES;

  if (!envOverride || envOverride.length === 0) {
    return baseRules;
  }

  const allowed = new Set(envOverride);
  return baseRules.filter((rule) => allowed.has(rule.caseId));
}
